INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100101_001", 0, "どんなに敵が大勢でも、みんなで\n力を合わせれば絶対大丈夫だよ！\nだから顔を上げてこう！\nごーごー！", "", "ヒヨリ", 4, 100101, 5, "vo_empress_100101_001", 1, 1, 1);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100101_002", 0, "ううっ、何度も戦う相手もいるけど\nあたし、負けたりなんてしないよ！\n今回だってみんなや騎士くんがいる\nフルパワーでいくよーっ！", "", "ヒヨリ", 4, 100103, 5, "vo_empress_100101_002", 1, 1, 2);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100101_003", 0, "うぅ…すごい力…！\n…でも、なんだか悲しそう\nこの人の気持ちを知りたい\nだからこそ…勝たなきゃ…！", "", "ヒヨリ", 4, 100103, 5, "vo_empress_100101_003", 1, 2, 3);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100101_004", 100101, "騎士くんの力があれば、\nあたしは絶対負けないよ！\nみんなが笑顔でいられるように\n一緒にがんばろう！", "", "ヒヨリ", 4, 100102, 5, "vo_empress_100101_004", 1, 3, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100201_001", 0, "わたしたちの世界のためにも\nこの世界のためにも、\n絶対に負けられない…！\nがんばろうね、騎士クン", "", "ユイ", 4, 100203, 5, "vo_empress_100201_001", 1, 1, 5);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100201_002", 0, "みんな、怪我したらすぐに教えて！\n…もう誰も失いたくないの\nそのために修行もしたんだから…\n大丈夫、絶対なんとかしてみせる！", "", "ユイ", 4, 100203, 5, "vo_empress_100201_002", 1, 1, 6);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100201_003", 0, "世界を『書き換え』するなんて…\nそんな未来、寂しいだけだよ…！\nお願い、これ以上みんなを\n傷つけないで…話を聞いて！", "", "ユイ", 4, 100203, 5, "vo_empress_100201_003", 1, 2, 7);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100201_004", 100201, "感じるよ、騎士クンの気持ち…\n抱きしめられてるみたいに\nあったかい…\nぜんぶ終わらせよう！", "", "ユイ", 4, 100202, 5, "vo_empress_100201_004", 1, 3, 8);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100301_001", 0, "厳しい戦いになるだろうな\n安心してくれ、何があっても\nキミは守る。…いや、違うな\n一緒に、世界を守ろう", "", "レイ", 4, 100301, 5, "vo_empress_100301_001", 1, 1, 9);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100301_002", 0, "手ごわい相手ばかりだな…\nだが引き下がるわけにはいかない\nこちらにだって譲れないものが\nあるんだ！", "", "レイ", 4, 100303, 5, "vo_empress_100301_002", 1, 1, 10);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100301_003", 0, "くっ…なんて力だ…！\n防ぐだけで精一杯…だが、\n例え剣が折れたとしても、\n私は最後まで戦い続ける！", "", "レイ", 4, 100303, 5, "vo_empress_100301_003", 1, 2, 11);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100301_004", 100301, "感じるよ、キミからの愛\nこれがあれば、私はどんな\n敵にだって打ち勝てる！\n見せてやろう、一緒に！", "", "レイ", 4, 100302, 5, "vo_empress_100301_004", 1, 3, 12);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100401_001", 0, "ミソギとにいちゃんはこれからも\n世界中を冒険して、ワクワクする\nお宝をたくさん見つけるんだ！\nワルモノなんかに邪魔させないよ！", "", "ミソギ", 4, 100401, 5, "vo_empress_100401_001", 1, 1, 13);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100401_002", 0, "わわ、なんかヤバそうな雰囲気…\nこういう時こそミソギの出番だね！\nとっておきのイタズラ決めて、\nピンチもひっくり返しちゃうよ！", "", "ミソギ", 4, 100401, 5, "vo_empress_100401_002", 1, 1, 14);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100401_003", 0, "うぅ…あの悪者、すごい迫力だよ…\nもしミソギたちが負けちゃったら、\nミソギもにいちゃんもこの世界も…\n全部おしまい、なんだよね…？", "", "ミソギ", 4, 100403, 5, "vo_empress_100401_003", 1, 2, 15);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100401_004", 100401, "ミソギたちが世界を救っちゃったら\nきっとみんなびっくりするよね！\nどんな顔して驚いてくれるかな…\nにひひ、なんかワクワクしてきた！", "", "ミソギ", 4, 100402, 5, "vo_empress_100401_004", 1, 3, 16);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100501_001", 0, "歴代オールヒーロー大進撃ッス～！\n自分は新世代のエースってとこッス\nかね？　さあ、ついてくるッス……\nあれ？　みんなどこ？　待って～", "", "マツリ", 4, 100501, 5, "vo_empress_100501_001", 1, 1, 17);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100501_002", 0, "敵は圧倒的な力で、こっちを絶望\nさせる気ッスかね？　だとしたら\n大誤算ッスよ！　むしろ自分の\n正義の魂に火をつけたんスから！", "", "マツリ", 4, 100501, 5, "vo_empress_100501_002", 1, 1, 18);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100501_003", 0, "足が……震えるッス……けど！\nこれは武者震いッス……！　だって\nヒーローは絶対に絶対にっ！\n敗北なんてしないんスから……っ！", "", "マツリ", 4, 100503, 5, "vo_empress_100501_003", 1, 2, 19);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100501_004", 100501, "さあ、手と手をつないで、\n二人で教えてやるッスよ！\nどんな物語でも、悪は必ずヒーロー\nに打ち倒されるってことを！", "", "マツリ", 4, 100502, 5, "vo_empress_100501_004", 1, 3, 20);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100601_001", 0, "ひゃぁんっ！\nもう、敵さんが脅かしてくるから\nアカリ、ヘンな声出ちゃいました…\nこういうの、よくないですよっ", "", "アカリ", 4, 100603, 5, "vo_empress_100601_001", 1, 1, 21);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100601_002", 0, "アカリ、お兄ちゃんとシタイコトが\nまだまだいっぱいあるんです！\nだから、私たちの大事な世界も…\n本気で守り抜いてみせますっ！", "", "アカリ", 4, 100601, 5, "vo_empress_100601_002", 1, 1, 22);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100601_003", 0, "うぅ…こんなに激しく攻められたら\nアカリ、もう壊れちゃいそうです…\nだけどまだまだ…戦えますっ！\nお兄ちゃんが一緒なんですからっ…", "", "アカリ", 4, 100603, 5, "vo_empress_100601_003", 1, 2, 23);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100601_004", 100601, "お兄ちゃんの愛を注いでもらって\nアカリ超絶パワーアップです！\nアカリらしく世界一かわいく、\n世界を救ってみせちゃいますよ！", "", "アカリ", 4, 100602, 5, "vo_empress_100601_004", 1, 3, 24);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100701_001", 0, "アイツらが野放しだと、ミヤコは\n安心してプリンを食べられないの\n今日のプリンと明日のプリンの\nためにも、絶対負けないの！", "", "ミヤコ", 4, 100701, 5, "vo_empress_100701_001", 1, 1, 25);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100701_002", 0, "前はミヤコ、悪いヤツに捕まって\n消されそうになって怖かったの…\nでも今度は全然怖くないの！\nオマエが一緒なら平気なの！", "", "ミヤコ", 4, 100702, 5, "vo_empress_100701_002", 1, 1, 26);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100701_003", 0, "むうぅ～っ、アイツしつこいの！\nこうなったら、オマエにも\nミヤコのプリン分けてやるの！\nダブルプリンパワーで頑張るの！", "", "ミヤコ", 4, 100703, 5, "vo_empress_100701_003", 1, 2, 27);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100701_004", 100701, "アイツはどんなに強くたって、\n独りぼっちのさびしいヤツなの\nでもオマエにはミヤコがいるの！\nミヤコたちなら絶対に勝てるの！", "", "ミヤコ", 4, 100702, 5, "vo_empress_100701_004", 1, 3, 28);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100801_001", 0, "相手が誰であれ、やることは同じ…\nそう…ボクの美しさを見せてあげる\nことさ！　予言しよう…絶世の美の\n前にはどんな敵もひれ伏すと、ね！", "", "ユキ", 4, 100801, 5, "vo_empress_100801_001", 1, 1, 29);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100801_002", 0, "少し待っていてくれる？　メイクを\n直さないと。避けられない戦いなら\nせめて美しいボクと戦えることを\n彼らには誇りに思ってほしいからね", "", "ユキ", 4, 100801, 5, "vo_empress_100801_002", 1, 1, 30);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100801_003", 0, "どうせ倒れるなら美しいままで散り\nたいな。ふふ、難しい望みかな…？\nそれでもボクは、最後まで美しく\nあがいてみせるよ、キミと一緒にね", "", "ユキ", 4, 100801, 5, "vo_empress_100801_003", 1, 2, 31);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100801_004", 100801, "ボクがいて、キミがいる。ボクたち\nが勝つのに、これ以上の理由はない\nよね。だって美しい者が勝つ未来の\nほうが、美しいエンディングだもの", "", "ユキ", 4, 100802, 5, "vo_empress_100801_004", 1, 3, 32);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100901_001", 0, "災厄の嵐が吹き荒れ、世界の命運は\n風前の灯が如く儚い。だが絶望には\nまだ早い！　希望はここに在り！\n灯火を掲げよう、盟友シグルドよ！", "", "アンナ", 4, 100901, 5, "vo_empress_100901_001", 1, 1, 33);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100901_002", 0, "終焉の日、滅びの刻来たれり、か…\nだが、幾度も転生を繰り返しながら\n戦いつづけた我らの宿命を思えば、\nこの程度取るに足らない…はずだ！", "", "アンナ", 4, 100903, 5, "vo_empress_100901_002", 1, 1, 34);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100901_003", 0, "くっ…なんという禍々しい魔力…！\nもはや世界の滅びも間近…しかし\n疾風の冥姫がここで退くわけには\nいかぬ！　しぶとく抗ってみせるぞ", "", "アンナ", 4, 100903, 5, "vo_empress_100901_003", 1, 2, 35);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_100901_004", 100901, "永遠の盟約で結ばれし魂の伴侶…\n世界を滅ぼさんとする災禍の剣も\nこの絆を断ち切ることはできない！\n覚悟するがいい、幻境竜后！！", "", "アンナ", 4, 100902, 5, "vo_empress_100901_004", 1, 3, 36);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101001_001", 0, "【自警団】のギルドマスターとして\nしゃんとして恥ずかしない姿を\n見せなあきまへんなぁ…王子はん\nしゃなりしゃなり、いきまひょ！", "", "マホ", 4, 101001, 5, "vo_empress_101001_001", 1, 1, 37);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101001_002", 0, "王子はん、服が破れてますえ？\nこれでよし…うん、完璧や♪\n戦いの中でも、王子はんには\n格好良う居てもらいたいさかいに♪", "", "マホ", 4, 101001, 5, "vo_empress_101001_002", 1, 1, 38);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101001_003", 0, "幻境竜后…大層なお名前してはる\nお后さまが勝負を挑んできはるなら\nうちも、マホマホ王国の姫として…\n正々堂々受けて立ちますえ！", "", "マホ", 4, 101003, 5, "vo_empress_101001_003", 1, 2, 39);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101001_004", 101001, "強い愛で結ばれた王子と姫を\n引き裂くことは誰にもできまへん\n王子はん…ふたりで一緒に！\nハッピーエンドを迎えまひょ！", "", "マホ", 4, 101002, 5, "vo_empress_101001_004", 1, 3, 40);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101101_001", 0, "お兄ちゃんがいれば百人力士っ！\n妹パワーも全開でいきますよ～♪\nどんな敵でもドンドンこいですっ！\nあれ？　ちょっと違いました？", "", "リノ", 4, 101101, 5, "vo_empress_101101_001", 1, 1, 41);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101101_002", 0, "これぞまさに『四面そば』…\n敵多すぎでもう大盛りですけど\n秘密結社の一員として、妹として\nこの世界の平和は守り通しますっ！", "", "リノ", 4, 101101, 5, "vo_empress_101101_002", 1, 1, 42);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101101_003", 0, "あれが幻境竜后…不思議な服…\nじゃなくて、空気がピリピリです…\nちょっとだけ怖いけど…妹として\n絶対に降参なんてしませんよ！", "", "リノ", 4, 101103, 5, "vo_empress_101101_003", 1, 2, 43);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101101_004", 101101, "私、もう迷いません！\nお兄ちゃんと一緒なら\nどんな敵だって倒しちゃいます！\n妹のポテンシャルは無限大ですよ！", "", "リノ", 4, 101102, 5, "vo_empress_101101_004", 1, 3, 44);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101201_001", 0, "どんなに大変な時でもキミと一緒に\nず～っと乗り越えてきたんだもん！\nだからっ、今回もきっと大丈夫！\n私の魔法できらーん☆　だよっ！", "", "ハツネ", 4, 101201, 5, "vo_empress_101201_001", 1, 1, 45);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101201_002", 0, "力を使いすぎると眠く…スヤァ…\nはっ、いけないいけない！\nキミ、私が寝ちゃったら起こして！\n…お、王子様のキスとかで…", "", "ハツネ", 4, 101202, 5, "vo_empress_101201_002", 1, 1, 46);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101201_003", 0, "も～！　容赦なさすぎだよぉ！\nそっ、それにさっきまでの戦いの\nせいで、ね、眠気がぁ～っ…\nハ、ハツネちゃん、ピ～ンチ…", "", "ハツネ", 4, 101203, 5, "vo_empress_101201_003", 1, 2, 47);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101201_004", 101201, "幻境竜后さんがどんなに強くても\n今のハツネちゃんは無敵なのだ～！\n大好きなキミと！　シオリンと！\nみんながいる世界を守っちゃうよ！", "", "ハツネ", 4, 101202, 5, "vo_empress_101201_004", 1, 3, 48);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101301_001", 0, "この世界にはね、たくさんの人の\n『好き』が詰まってるんだよ\nそれをぶち壊すなんて鬼畜の所業\nナナカちゃんが許しはしないぜ！", "", "ナナカ", 4, 101301, 5, "vo_empress_101301_001", 1, 1, 49);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101301_002", 0, "見るからにヤバい奴らが勢ぞろい！\nでもみんなの世界が狙われてんのに\n日和ってる奴いる？いねえよなぁ！\n全員ぶっ飛ばして世界を救うぞ！！", "", "ナナカ", 4, 101301, 5, "vo_empress_101301_002", 1, 1, 50);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101301_003", 0, "あとはラスボスを倒せば勝利ッ！\n第３部完！　…とはいかない感じ？\nていうか逆にピンチな気配？\nどっどうしよう、どうすれば！？", "", "ナナカ", 4, 101303, 5, "vo_empress_101301_003", 1, 2, 51);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101301_004", 101301, "幻境竜后…確かに強敵だったね\nでも今はもう負ける気がしないかな\nだって私は、ただのナナカじゃない\n超ナナカちゃんだから…！", "", "ナナカ", 4, 101302, 5, "vo_empress_101301_004", 1, 3, 52);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101401_001", 0, "あちらにもなかなかの陰謀家がいる\nようだね。彼女らの最大の誤算は\nここに希代の名探偵がいることさ！\nさあ助手くん。真実を勝ち取ろう！", "", "カスミ", 4, 101401, 5, "vo_empress_101401_001", 1, 1, 53);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101401_002", 0, "仕方ない、こうなったら奥の手だ\nミスティ！　セオリー！　…って\nこらぁっ！　変身の最中は待って\nくれるのがお約束だよ！？", "", "カスミ", 4, 101401, 5, "vo_empress_101401_002", 1, 1, 54);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101401_003", 0, "なっ…なんだい、この悪寒は…\n触れてはならない何か…いいや！\n名探偵たるもの巨悪に恐れをなす\nわけにはいかない。絶対に…！", "", "カスミ", 4, 101403, 5, "vo_empress_101401_003", 1, 2, 55);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101401_004", 101401, "どんな哀しみでさえ、道理を穢す\n理由にしてはならない。さあ、\nお縄につくんだ。史上最大の迷宮\n事件…終わらせるのは…この私だ！", "", "カスミ", 4, 101402, 5, "vo_empress_101401_004", 1, 3, 56);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101501_001", 0, "先生は…ううん、先生たちは。\n絶対に負けません。みんなに傷一つ\nつけさせたりはしないわ…！", "", "ミサト", 4, 101501, 5, "vo_empress_101501_001", 1, 1, 57);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101501_002", 0, "とっても強大な敵ばかりね…\nでも、大丈夫。焦らず落ち着いて\n戦いましょう。先生がついてるわ\n長引いても、あきらめないで…！", "", "ミサト", 4, 101501, 5, "vo_empress_101501_002", 1, 1, 58);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101501_003", 0, "幻境竜后さんの力…すごいわ…\nううん、怖がってる暇なんてないの\n森のみんなを守るためにも…！\n好き勝手したら「めっ」ですからね", "", "ミサト", 4, 101501, 5, "vo_empress_101501_003", 1, 2, 59);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101501_004", 101501, "あなたと一緒なら\n負けたりなんか絶対にしないわ\n最後の一撃まで、\nがんばりましょうね♪", "", "ミサト", 4, 101502, 5, "vo_empress_101501_004", 1, 3, 60);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101601_001", 0, "ツヨそーな敵ばっかりで\nテン下げってカンジだけど\nとりま、うちとヒデサイが\n一緒なら乗り越えられるっしょ！", "", "スズナ", 4, 101601, 5, "vo_empress_101601_001", 1, 1, 61);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101601_002", 0, "あっ、まってヒデサイ\nマントずれてるから直してあげる\n…よし！　こーゆう時こそ\nおしゃれでテン上げしなきゃね♪", "", "スズナ", 4, 101601, 5, "vo_empress_101601_002", 1, 1, 62);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101601_003", 0, "おにヤバすぎて超わろ～…でもでも\nどうにかやるしかないっしょ～\n勝利のランウェイ遠すぎだけど\nうちら諦めんのはダメだよね～！", "", "スズナ", 4, 101601, 5, "vo_empress_101601_003", 1, 2, 63);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101601_004", 101601, "アオハルでバイブス爆上げ♪\n今のうちらは、ムテキだよ～\nハッピーで、もにカワな未来だって\n一緒にゲットするしかないっしょ♪", "", "スズナ", 4, 101602, 5, "vo_empress_101601_004", 1, 3, 64);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101701_001", 0, "歌ったり踊ったり、\nキミと一緒にやりたいことが\nばんないあるからね～！\n絶対に負けられないさ～！", "", "カオリ", 4, 101701, 5, "vo_empress_101701_001", 1, 1, 65);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101701_002", 0, "ううっ強そうな敵ばっかりさ～！\n長丁場の戦いにはやっぱりこれよ～\nサーターアンダギー！\n栄養付けて平和を守るさ～♪", "", "カオリ", 4, 101701, 5, "vo_empress_101701_002", 1, 1, 66);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101701_003", 0, "うぅ～、幻境竜后、でーじ強いね～\n私たちも引き下がる気はないよ～！\nどんなに時間がかかっても、絶対に\n諦めたりしないさ～！　だよね～？", "", "カオリ", 4, 101703, 5, "vo_empress_101701_003", 1, 2, 67);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101701_004", 101701, "キミのくれた情熱が、\n私の中で熱く燃え滾ってるよ！\n最高の一撃、キミに見せるさ～！", "", "カオリ", 4, 101702, 5, "vo_empress_101701_004", 1, 3, 68);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101801_001", 0, "学校生活の邪魔はさせないわ\nだって私、みんなの先生だもの\n明日の授業も世界のことも\n全部守ってみせるんだから！", "", "イオ", 4, 101801, 5, "vo_empress_101801_001", 1, 1, 69);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101801_002", 0, "やん！　なんて手ごわい人たちなの\nでも諦めないわ。難しい問題だって\n落ち着いてやればちゃんと解けるの\n戦いも同じよ…いきましょう！", "", "イオ", 4, 101801, 5, "vo_empress_101801_002", 1, 1, 70);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101801_003", 0, "これが、幻境竜后さんの力…圧倒\nされちゃいそう。でも、怖がってる\n場合じゃないわ。先生は絶対に、\nここから退かないわ！", "", "イオ", 4, 101803, 5, "vo_empress_101801_003", 1, 2, 71);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_101801_004", 101801, "二人の絆があれば、\n怖いものなんてないわ\n先生と力を合わせて─\nいきましょう♪", "", "イオ", 4, 101802, 5, "vo_empress_101801_004", 1, 3, 72);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102001_001", 0, "す、すごく強そうな人がいっぱい…\nミミ、怖くてぶるぶるしちゃうけど\nでも泣いちゃったりはしないよっ\nおにいちゃんがいっしょだもん…！", "", "ミミ", 4, 102003, 5, "vo_empress_102001_001", 1, 1, 73);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102001_002", 0, "プチグリフォンさんもハナちゃんも\nみゅ～ちゃんも…きっとみんな、\nミミのこと応援してくれてるよね\nだからミミも、がんばるよっ…！", "", "ミミ", 4, 102003, 5, "vo_empress_102001_002", 1, 1, 74);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102001_003", 0, "あ、あの竜の人…本気になったら、\nすごく強そうだよ…！このままじゃ\nみんなもミミたちも負けちゃう…？\nやだ、ミミそんなのいやだよっ…", "", "ミミ", 4, 102003, 5, "vo_empress_102001_003", 1, 2, 75);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102001_004", 102001, "おにいちゃんがくれた元気、\n今度はミミたちから届けようね\nもう大丈夫、心配しないでって…\n世界中の、大切なお友だちに…！", "", "ミミ", 4, 102002, 5, "vo_empress_102001_004", 1, 3, 76);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102101_001", 0, "怖い人たちがいっぱいですぅ…！\n…でも、みんな頑張ってる…私も\nベルルちゃんみたいに勇気を出して\n…祝福の音を鳴らしましょう！", "", "クルミ", 4, 102101, 5, "vo_empress_102101_001", 1, 1, 77);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102101_002", 0, "お兄ちゃん、私、がんばりますぅ\n『ロスト』したお父さんたちの\nためにも…！　怖い時こそ前を見て\n戦ってみせますからっ…！", "", "クルミ", 4, 102101, 5, "vo_empress_102101_002", 1, 1, 78);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102101_003", 0, "っ…すごい迫力ですぅ…！\nでも…絶望は必ず乗り越えられる\n胸の中の、希望の音色を信じて…\n逃げたりなんか、しませんよぅ…っ", "", "クルミ", 4, 102101, 5, "vo_empress_102101_003", 1, 2, 79);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102101_004", 102101, "みんなに勇気を与えるために\n主役にも英雄にもなってみせますぅ\nお兄ちゃんがいてくれるなら\n私はなんでもできるんです…！", "", "クルミ", 4, 102102, 5, "vo_empress_102101_004", 1, 3, 80);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102201_001", 0, "こ、これくらいの敵、問題ないわ！\nほんとはちょっと怖いけど…\nゲームの世界を救うことくらい\nこっちは慣れっこなんだから…！", "", "ヨリ", 4, 102201, 5, "vo_empress_102201_001", 1, 1, 81);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102201_002", 0, "ここで私たちが負けたら、\n世界が終わっちゃうなんて…\n絶対に認めるわけにはいかないわ！\nアンタも覚悟決めなさいよっ！", "", "ヨリ", 4, 102201, 5, "vo_empress_102201_002", 1, 1, 82);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102201_003", 0, "ここからが本当の戦いってこと？\nならもう、とことんやってやるわ！\nゲーマーってのは、敵が手強いほど\n燃えてくる生き物なのよ！", "", "ヨリ", 4, 102203, 5, "vo_empress_102201_003", 1, 2, 83);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102201_004", 102201, "絶対に帰りたい理由ができた…\nそう思うだけで、いくらでも力が\n湧いてくるの。これならもう、\n文句なしの勝ち確よねっ！", "", "ヨリ", 4, 102202, 5, "vo_empress_102201_004", 1, 3, 84);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102301_001", 0, "私もみんなと一緒に戦うよ！\n悪い人たちはフルスイングで\nあっという間に倒しちゃうから！\n『おうっ！　全員かかってこい！』", "", "アヤネ", 4, 102301, 5, "vo_empress_102301_001", 1, 1, 85);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102301_002", 0, "本当はちょっとだけ怖いけど…\nぷうきちもお兄ちゃんも一緒だもん\n力を合わせて世界を守っちゃうよ\n絶対に負けないんだから！", "", "アヤネ", 4, 102303, 5, "vo_empress_102301_002", 1, 1, 86);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102301_003", 0, "ううっあの人、すごく怖いけど\n逃げないよ、戦うって決めたもん\nね、お兄ちゃん、ぷうきち！\n『ここが踏ん張りどころだぞ！』", "", "アヤネ", 4, 102303, 5, "vo_empress_102301_003", 1, 2, 87);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102301_004", 102301, "お兄ちゃんが約束してくれたもん\n今の私ならどんな悪いやつにも\n負けないよ！　宇宙人でもなんでも\n一撃で追い返しちゃうんだから♪", "", "アヤネ", 4, 102302, 5, "vo_empress_102301_004", 1, 3, 88);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102501_001", 0, "大変なことになっちゃいましたね…\nで、でも怖がっていられません！\nお嬢さまのことも、あなたのことも\n私が精一杯お支えします！", "", "スズメ", 4, 102503, 5, "vo_empress_102501_001", 1, 1, 89);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102501_002", 0, "世界の命運がかかってますから\nドジなんてしてられません！\n…って、ああっ！　言ったそばから\nまた魔法が暴走しちゃいましたっ！", "", "スズメ", 4, 102503, 5, "vo_empress_102501_002", 1, 1, 90);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102501_003", 0, "す、すごい力です…！\nでもお嬢さまや大切な人をおいて\n逃げるわけにはいきません！\nどこまでもお供します…！", "", "スズメ", 4, 102503, 5, "vo_empress_102501_003", 1, 2, 91);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102501_004", 102501, "大切な人と力を合わせれば、\nドジな私でも世界を救えるんです！\n世界規模…いえ、宇宙規模の大掃除\n始めちゃいますよ～っ！", "", "スズメ", 4, 102502, 5, "vo_empress_102501_004", 1, 3, 92);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102601_001", 0, "ええー？　こんだけ人数いるならさ\n一人ぐらいいなくても…\n…って空気じゃないわけね\nはいはい、あたしも働きますよー", "", "リン", 4, 102603, 5, "vo_empress_102601_001", 1, 1, 93);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102601_002", 0, "うぅ…あんなのもうバグでしょ！？\nこんな無理ゲーに参戦したんだもん\n終わったらしばらく働かないから！\nダラダラゴロゴロするからね～！", "", "リン", 4, 102603, 5, "vo_empress_102601_002", 1, 1, 94);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102601_003", 0, "見てよあのビジュアルさー\nまさにラスボスって感じじゃん…\nでも、どんなゲームでもボスは\n倒せるわけだし…はぁ、やるかー", "", "リン", 4, 102603, 5, "vo_empress_102601_003", 1, 2, 95);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102601_004", 102601, "ここまで来たら後には退けないし\n正真正銘のラスボス戦ってんなら\nあたしも─気合い入れて\n少しぐらいイイとこ見せないとね！", "", "リン", 4, 102602, 5, "vo_empress_102601_004", 1, 3, 96);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102701_001", 0, "有象無象のクズ虫が、私たちの\n幸せを阻もうとしているようですね\nあぁ、なんて忌々しいのでしょう…\n残らずすり潰しますわ、クスクス…", "", "エリコ", 4, 102701, 5, "vo_empress_102701_001", 1, 1, 97);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102701_002", 0, "クスクス…あら、失礼しましたわ\nこの連中を駆逐すれば、私たちの\n絆はより強く…そんな想像をしたら\n思わず…クスクスクス、クスクス", "", "エリコ", 4, 102701, 5, "vo_empress_102701_002", 1, 1, 98);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102701_003", 0, "あの女…下らない言葉であなた様を\n誑かそうとしたとか。万死に値する\n罪…身の程を思い知らせてやるまで\n決して退きはしませんわ…", "", "エリコ", 4, 102703, 5, "vo_empress_102701_003", 1, 2, 99);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102701_004", 102701, "『壊し屋』と呼ばれる私ですが…\n今はこの力、創るために振るいます\nあなた様との愛、未来…\nクスクス…さあ参りましょう…♪", "", "エリコ", 4, 102702, 5, "vo_empress_102701_004", 1, 3, 100);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102801_001", 0, "しっかり頭数揃えてきたわね…\nでもこの程度の力に屈するような\nあたしたちじゃないんだから\nあんたも、サポート頼んだわよ！", "", "サレン", 4, 102801, 5, "vo_empress_102801_001", 1, 1, 101);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_102801_002", 0, "ちょっと！　なんか向こうに\n教育に悪そうなのがいるんだけど！\nあいつは子どもたちの目に入る前に\nあたしたちで倒すわよ。いい？", 10000, "サレン", 4, 102801, 3, "vo_empress_102801_002", 1, 4002, 102);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102801_003", 0, "もう、強すぎて参っちゃうわね…\nでも諦めるわけにはいかないわ\nこっちだって守らなきゃいけない\nものがたくさんあるんだから！", "", "サレン", 4, 102803, 5, "vo_empress_102801_003", 1, 2, 103);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102801_004", 102801, "いつも以上に負ける気がしないわ\nこれもあんたと気持ちが通じた\nおかげね。あんたが側にいる限り、\nあたしはずっと無敵なんだから！", "", "サレン", 4, 102802, 5, "vo_empress_102801_004", 1, 3, 104);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102901_001", 0, "この世界が終わっちゃうって…\nアイドル活動も卒業ってコト！？\nファンのみんなが黙ってないよ！\nもちろん私だって…！", "", "ノゾミ", 4, 102903, 5, "vo_empress_102901_001", 1, 1, 105);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102901_002", 0, "どんな強い敵にだって屈しない…\n歌って踊って戦うアイドルになる！\nあの日に誓った願い、私の希望！\n今こそ、果たして見せるんだから！", "", "ノゾミ", 4, 102903, 5, "vo_empress_102901_002", 1, 1, 106);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102901_003", 0, "幻境竜后…ダンスも歌も、あなたに\nとって価値はないかもしれないけど\n私はこのステージから逃げたり\nなんてしない！　アイドルとして！", "", "ノゾミ", 4, 102903, 5, "vo_empress_102901_003", 1, 2, 107);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_102901_004", 102901, "星を書き換えるなんてすごい発想…\nプロデューサーとか向いてるかも？\nって、今はそんな場合じゃないか！\n覚悟してよね、幻境竜后！", "", "ノゾミ", 4, 102901, 5, "vo_empress_102901_004", 1, 3, 108);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103001_001", 0, "ショーグンの天下統一を阻む者は\n誰であろうと許しまセン！\nショーグン！　ここはチューシン\nニノンにお任せアーレー！", "", "ニノン", 4, 103001, 5, "vo_empress_103001_001", 1, 1, 109);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103001_002", 0, "むむむ…待ち受けているのは強敵\nばかり…それでも退きまセン！\n超烈火之紅蓮旋風で、\nまとめて討ち取ってみせまショウ！", "", "ニノン", 4, 103001, 5, "vo_empress_103001_002", 1, 1, 110);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103001_003", 0, "な、なんて強さ…このままでは、\nワタシたちは負けてしまいます…\n…いいえ。いいえ！　ショーグンの\nためにも、諦めることなど…っ！", "", "ニノン", 4, 103003, 5, "vo_empress_103001_003", 1, 2, 111);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103001_004", 103001, "感じマス、ショーグンの愛を…！\n今ならどんな敵が来ても、\nカッサイ、ボンサイ、\nオチャノコサイサイデース！", "", "ニノン", 4, 103002, 5, "vo_empress_103001_004", 1, 3, 112);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103101_001", 0, "この世界が、明日を迎えることなく\n滅んでしまうかもしれない…\n運命の岐路が、目の前にあります\n抗えるのは、私たちだけです…！", "", "シノブ", 4, 103101, 5, "vo_empress_103101_001", 1, 1, 113);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103101_002", 0, "何よりも色濃い死の気配が、\n世界に満ちていくのを感じます\nでも、倒れるわけにはいきません\n最後まで戦いましょう、全力で", "", "シノブ", 4, 103101, 5, "vo_empress_103101_002", 1, 1, 114);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103101_003", 0, "これほどまでに強大な力なんて…\n占いも、未来は滅びの闇に覆われ\nつつある、と出ています…それでも\n希望を手放すわけには…！", "", "シノブ", 4, 103103, 5, "vo_empress_103101_003", 1, 2, 115);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103101_004", 103101, "命ある者にとって、死の運命は\n決して避けられないもの…\nでも、今この時ではないはずです\n戦いましょう、未来のために…！", "", "シノブ", 4, 103101, 5, "vo_empress_103101_004", 1, 3, 116);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103201_001", 0, "これ以上の狼藉は許しません！\nウィスタリア家の名に懸けて、\nこの世界の人々を守ります…必ずや\n貴人としての役目を果たしますわ！", "", "アキノ", 4, 103201, 5, "vo_empress_103201_001", 1, 1, 117);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103201_002", 0, "互いを利するウィンウィンの関係\nそれが商売の鉄則です。力を振るい\n一方的に望みを押し付けるなんて、\n倒産まっしぐらですわよっ！", "", "アキノ", 4, 103201, 5, "vo_empress_103201_002", 1, 1, 118);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103201_003", 0, "幻境竜后…すさまじい力ですわね\n世界を意のままにするという野望も\n決して絵空事ではないのでしょう…\nそれでも私は…諦めませんわよ！", "", "アキノ", 4, 103203, 5, "vo_empress_103201_003", 1, 2, 119);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103201_004", 103201, "人々を守ることが力ある者の務め…\nそしてあなたさまと共に生きること\nそれが私の務めであり願いですわ！\nこの想いは、止まりませんわよ！", "", "アキノ", 4, 103202, 5, "vo_empress_103201_004", 1, 3, 120);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103301_001", 0, "こんな舞台で漫才したって\nみんなもお天道さんもどんよりだべ\n安心して笑ってられる世界を\nオラたちで取り戻すど！　おー！", "", "マヒル", 4, 103301, 5, "vo_empress_103301_001", 1, 1, 121);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103301_002", 0, "お、おっかねぇ連中だ…！\nでも…スベっちまう怖さに比べりゃ\nマシだべな！　あははっ！\nみんなの笑顔は、オラが守るべ！", "", "マヒル", 4, 103301, 5, "vo_empress_103301_002", 1, 1, 122);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103301_003", 0, "あの子、芸人として光りそうだべな\n幻境竜后なんて仰々しい名前も…\nノーヴィジョンズノープロブレム！\n…あたた！　激しいツッコミだべ！", "", "マヒル", 4, 103303, 5, "vo_empress_103301_003", 1, 2, 123);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103301_004", 103301, "逆境も笑顔で切り開く…\nあんちゃんと一緒なら\nできる気がすんだ\nオラたちの芸人魂、見せてやるべ！", "", "マヒル", 4, 103302, 5, "vo_empress_103301_004", 1, 3, 124);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103401_001", 0, "元…ううん、正しき聖騎士として\nここでやらなきゃいつやるのよ…！\n必ずみんなを守りきってみせるわ\n怪我をした人は私のところへ！", "", "ユカリ", 4, 103401, 5, "vo_empress_103401_001", 1, 1, 125);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103401_002", 0, "…んぐっ…ごくっ…ぷは～っ♪\nよぉし気合十分らわ～っ！\nこら～幻境竜后～っ！　隠れて\nないでかかってきなさ～い！", "", "ユカリ", 4, 103401, 5, "vo_empress_103401_002", 1, 1, 126);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103401_003", 0, "ひっく…ふぇ？　な、なに……？\nと、とっても大きいのが見えりゅ…\n…なっ、なによこれえぇぇ！\nこ、これが幻境竜后の姿なのぉ～っ", "", "ユカリ", 4, 103403, 5, "vo_empress_103401_003", 1, 2, 127);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103401_004", 103401, "私は無敵らのよ～♪　この世界と\nキミと築く\n素敵な未来のために…幻境竜后！\nぶっとばしてやるわぁ～っ！", "", "ユカリ", 4, 103402, 5, "vo_empress_103401_004", 1, 3, 128);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103601_001", 0, "ここで私たちが諦めたら、このまま\n世界が終わっちゃう！　そんなの\n絶対ダメです！　負けられません！\n私たちで全部退治しちゃいますよ！", "", "キョウカ", 4, 103603, 5, "vo_empress_103601_001", 1, 1, 129);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103601_002", 0, "うぅ、ふしんしゃがいっぱいです！\n…でも、このくらいへっちゃらです\nお母さんが心配する前に、早く\n片付けておうちに帰りましょう！", "", "キョウカ", 4, 103603, 5, "vo_empress_103601_002", 1, 1, 130);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103601_003", 0, "あれが私たちの敵、幻境竜后…\nほ、本当に勝てるんでしょうか…？\n立ってるだけで体が震えて…でも、\n弱気になっちゃダメですよねっ…！", "", "キョウカ", 4, 103601, 5, "vo_empress_103601_003", 1, 2, 131);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103601_004", 103601, "正直に言うと…まだ少し怖いです\n我慢したって怖くて体が震えます\nでも、あなたがいてくれるから…\n勇気だって同じくらい湧いてきます", "", "キョウカ", 4, 103602, 5, "vo_empress_103601_004", 1, 3, 132);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103701_001", 0, "滅ぼすための力に、守るための力が\n屈するわけにはいかないよ。\nこの剣の誇りに賭けて、必ず止める\nさあ、来い！　ミクマ流が相手だ！", "", "トモ", 4, 103701, 5, "vo_empress_103701_001", 1, 1, 133);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103701_002", 0, "追いかけっこでもしようか\n鬼さんこちら♪　…って、まだ\n来るの！？　不意打ちされる側に\nなるのは趣味じゃないんだけどな！", "", "トモ", 4, 103701, 5, "vo_empress_103701_002", 1, 1, 134);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103701_003", 0, "踏み込めない…踏み込む隙がない…\n向きあってるだけで精一杯なんて…\nで、でも…こんなところで\n剣を捨てるわけにはっ…！", "", "トモ", 4, 103701, 5, "vo_empress_103701_003", 1, 2, 135);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103701_004", 103701, "勝機は私の中にあったんだ…！\nあなたとの、\n一番強くて絶対に消えない絆\nそれが、あいつを倒す力をくれる！", "", "トモ", 4, 103702, 5, "vo_empress_103701_004", 1, 3, 136);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103801_001", 0, "手ごわい相手ですね…\nでも、不思議と怖くありません\nあなたと力を合わせれば\n何とかなるって信じていますから", "", "シオリ", 4, 103801, 5, "vo_empress_103801_001", 1, 1, 137);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103801_002", 0, "あなたの応援で、私の胸に\n愛と希望が満ち溢れています…\n今こそ魔法狩人ピュアリー★シオリ\nに大変身する時なのかも…？", "", "シオリ", 4, 103801, 5, "vo_empress_103801_002", 1, 1, 138);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103801_003", 0, "とてつもない力ですね…\nでも、諦めたくありません\n何度だって立ち上がってみせます\n今までと同じように…！", "", "シオリ", 4, 103803, 5, "vo_empress_103801_003", 1, 2, 139);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_103801_004", 103801, "今の私に怖いものなんてありません\nあなたとの愛の力がありますから♪\n…少し舞い上がり過ぎですかね？\nふふ、気を引き締めてがんばります", "", "シオリ", 4, 103802, 5, "vo_empress_103801_004", 1, 3, 140);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104001_001", 0, "進んで目立ちたくはないですけど…\nと、ともっ…友達を守るためなら！\nＢＢ団として、勇気を振り絞って…\n団長さんと一緒に戦います！", "", "アオイ", 4, 104001, 5, "vo_empress_104001_001", 1, 1, 141);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104001_002", 0, "いいい、一緒に戦う仲間がこんなに\nいてくれるなんて、こ、心強いの\n助太郎～っ！　私も末席で参加し…\nじゃなくてっ！　全力で戦います！", "", "アオイ", 4, 104002, 5, "vo_empress_104001_002", 1, 1, 142);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104001_003", 0, "ううっ、手も足も声も震えてます…\nで、でも逃げも隠れもしませんよっ\n逃げたらぼっちが廃ります！", "", "アオイ", 4, 104003, 5, "vo_empress_104001_003", 1, 2, 143);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104001_004", 104001, "私はひとりぼっちじゃない…\n団長さんと繋がった絆があるから\nどんな敵だって怖くないですっ！\n行きましょう、団長さんっ！", "", "アオイ", 4, 104002, 5, "vo_empress_104001_004", 1, 3, 144);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104201_001", 0, "やめてくれる気はなさそうです\nそれなら私も、絶対にここを\n動きはしません…！　だって\n私は……ワガママですからっ！", "", "チカ", 4, 104203, 5, "vo_empress_104201_001", 1, 1, 145);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104201_002", 0, "私の唱喚術は人を守るためのもの…\nこの世界の森羅万象を護るための\nもの。今こそ、声の限り歌います\nこの子たちと、あなたと共に！", "", "チカ", 4, 104201, 5, "vo_empress_104201_002", 1, 1, 146);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104201_003", 0, "精霊たちが震えてる…今までの\n敵とは訳が違うってことですよね…\n私もここに立っているのが精一杯…\n怖いけど…でも！　退きません…！", "", "チカ", 4, 104203, 5, "vo_empress_104201_003", 1, 2, 147);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104201_004", 104201, "今なら歌える気がします。ずっと\n探していた、誰かの心を震わせる歌\n幻境竜后…孤独なあなたの心にも\n私たちの歌が届くように…！", "", "チカ", 4, 104201, 5, "vo_empress_104201_004", 1, 3, 148);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104301_001", 0, "敵さんがどんだけ強くったって\n後には退けねぇんだ！　そうだろ、\nさぁ、覚悟しやがれよ！", "", "マコト", 4, 104301, 5, "vo_empress_104301_001", 1, 1, 149);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104301_002", 0, "くっ、敵の連中、ずいぶんな戦力\n揃えてきやがった。けど、\n数でも気合でも負けやしねぇ！\nあたしが嚙み砕いてやる！", "", "マコト", 4, 104301, 5, "vo_empress_104301_002", 1, 1, 150);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104301_003", 0, "幻境竜后とやら…マジで\n洒落になんねえな。だからって\n引き下がるわけにゃいかねえ！\n持ちこたえてやるぜ！", "", "マコト", 4, 104303, 5, "vo_empress_104301_003", 1, 2, 151);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104301_004", 104301, "どんな強い敵でも\n恐れる必要なんてないよな\nさあ、いっしょに─最大パワーで\nブチのめしてやろうぜっ！", "", "マコト", 4, 104302, 5, "vo_empress_104301_004", 1, 3, 152);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104401_001", 0, "ここはいずれわらわが支配する世界\nつまり、わが領地に等しきもの…\n奴らのような不届き者の蛮行、\n見過ごすわけにはいかぬわ！", "", "イリヤ", 4, 104401, 5, "vo_empress_104401_001", 1, 1, 153);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104401_002", 0, "厳しい戦いになりそうじゃな…\nお主もわらわから離れるでないぞ\nも、もちろん、大人の姿を保つのに\n都合がいいからというだけじゃ！", "", "イリヤ", 4, 104401, 5, "vo_empress_104401_002", 1, 1, 154);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104401_003", 0, "何とも恐ろしく禍々しい力じゃ…\nだが、我が意志は決して挫けぬ\n高貴なる吸血鬼の誇りに懸けて、\n最後まで戦い抜いてみせようぞ", "", "イリヤ", 4, 104401, 5, "vo_empress_104401_003", 1, 2, 155);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104401_004", 104401, "己が誰を敵に回したのかを、\n骨の髄まで知らしめてやろうぞ\nここにいるのは固き絆で結ばれし\n伝説の吸血鬼とその眷属じゃ！", "", "イリヤ", 4, 104401, 5, "vo_empress_104401_004", 1, 3, 156);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104501_001", 0, "とっても強そうな敵ですっ…\n当然、攻撃も強烈になるはず…\nドＳさん、ここはどうかクウカに、\n先頭をお任せください！　ぐふふ♪", "", "クウカ", 4, 104501, 5, "vo_empress_104501_001", 1, 1, 157);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104501_002", 0, "安心してドＳさんに虐げてもらう\nためにもクウカは負けられませんっ\nこの世界で一番のドＭとして、\n全力で責められに行ってきますっ！", "", "クウカ", 4, 104501, 5, "vo_empress_104501_002", 1, 1, 158);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104501_003", 0, "ううっ、刺激が強すぎますよ…っ\nだけど、ドＭのプライドにかけて\nここで退くわけにはいきませんっ！\nドＳさんのこと、守り抜きます…っ", "", "クウカ", 4, 104503, 5, "vo_empress_104501_003", 1, 2, 159);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104501_004", 104501, "その視線は、『全部終わったらたっ\nぷり調教してやるからな』という\n意味ですね！　ぐふふっ…♪　負け\nられない理由がまた一つできました", "", "クウカ", 4, 104502, 5, "vo_empress_104501_004", 1, 3, 160);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104601_001", 0, "強そうなやつらが目白押しにゃ～\n短期戦でどうにかならないなら…\n長丁場に向けて、特別価格の\nたい焼きはいかがかにゃ～？", "", "タマキ", 4, 104601, 5, "vo_empress_104601_001", 1, 1, 161);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104601_002", 0, "ファントムキャッツは\n狙った獲物を逃がさないにゃ！\nあたしたちの未来を手に入れるまで\nとことんやってやるにゃ～！", "", "タマキ", 4, 104601, 5, "vo_empress_104601_002", 1, 1, 162);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104601_003", 0, "にゃにゃっ、これが幻境竜后…\nとんでもない力だにゃ\nでも、ここで逃げたらファントム\nキャッツの名が廃るにゃ～！", "", "タマキ", 4, 104603, 5, "vo_empress_104601_003", 1, 2, 163);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104601_004", 104601, "ファントムキャッツにかかれば\nどんなに強い悪党でも\n滅びる運命にゃ！\nとっておきの一撃、キメるにゃ～！", "", "タマキ", 4, 104602, 5, "vo_empress_104601_004", 1, 3, 164);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104701_001", 0, "全軍展開！　敵の一体たりとも\nこの先へは進ませるな\n苦しいときは、私の背中を見るんだ\n我々は決して折れはしない！", "", "ジュン", 4, 104701, 5, "vo_empress_104701_001", 1, 1, 165);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104701_002", 0, "少年…\n最前線は危険だが、下がるつもりは\nないのか？　ふふ、やはり強情だな\nならば、私の隣を絶対に離れるな", "", "ジュン", 4, 104701, 5, "vo_empress_104701_002", 1, 1, 166);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104701_003", 0, "な…なんだ…この冷たい闘気は…！\nみんな、いったん退がれ！\n安心しろ、ここは私が防ぎきる\n…たとえ…この身に代えても", "", "ジュン", 4, 104701, 5, "vo_empress_104701_003", 1, 2, 167);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104701_004", 104701, "幻境竜后、貴様は絶対に勝てないよ\n自分の身以上に、大切な誰かを\n守りたいという、人間の持つ尊い\n想いを、知ることのない貴様は…！", "", "ジュン", 4, 104701, 5, "vo_empress_104701_004", 1, 3, 168);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104801_001", 0, "バイト仲間とこの世界のみんなを\n守るために！　私たちのやるべき\nことはただ一つ！　いいわね？\n─最高の効率で倒すわよ！", "", "ミフユ", 4, 104801, 5, "vo_empress_104801_001", 1, 1, 169);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104801_002", 0, "相手も数が多いし、短期決戦とは\nいかないわね…って！　早く\n勝たなきゃバイトに遅刻しちゃう\nもっと効率アップしていくわよ！", "", "ミフユ", 4, 104801, 5, "vo_empress_104801_002", 1, 1, 170);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104801_003", 0, "幻境竜后……本当に圧倒的な力ね\nだからってそう簡単に諦められる\nわけはないわよね。たとえそれが\n非効率的な判断だとしても……！", "", "ミフユ", 4, 104803, 5, "vo_empress_104801_003", 1, 2, 171);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104801_004", 104801, "こんなに迂遠で非効率的な計画を\n立てる敵になんて負けないわ！\n効率を極めた私たちの一撃を\n叩きつけてやりましょう！", "", "ミフユ", 4, 104802, 5, "vo_empress_104801_004", 1, 3, 172);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104901_001", 0, "安心していいよ、弟くん♪\n弟くんには指一本触れさせない！\n絶対に弟くんを守るから…だって\nそれがお姉ちゃんの役目だもんね！", "", "シズル", 4, 104902, 5, "vo_empress_104901_001", 1, 1, 173);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104901_002", 0, "準備はできてる、弟くん？\n不安なら手をつないであげよっか？\n大丈夫、お姉ちゃんと弟くんなら\n悪いやつらを全部倒せるはず♪", "", "シズル", 4, 104902, 5, "vo_empress_104901_002", 1, 1, 174);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104901_003", 0, "幻境竜后…手強そうだね…\nでも諦めないよ、絶対に！\n弟くんとお姉ちゃんの大切な世界\nきっと守り抜いてみせるんだから！", "", "シズル", 4, 104903, 5, "vo_empress_104901_003", 1, 2, 175);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_104901_004", 104901, "お姉ちゃんと弟くんの力を合わせて\n二人の未来を、みんなの未来を\n一緒に守ろっ！　あ、終わったら\nたくさん甘えさせてあげるからね♪", "", "シズル", 4, 104902, 5, "vo_empress_104901_004", 1, 3, 176);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105001_001", 0, "アブナイキレイなお姉さんはね\n『ふれーばー』だから許されるの！\nこんなメチャクチャにするなんて…\n本物の大人のレディが勝負よ勝負！", "", "ミサキ", 4, 105001, 5, "vo_empress_105001_001", 1, 1, 177);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105001_002", 0, "アタシは全世界代表の\n大人のレディなんだから！\nアンタ！\nしっかりエスコートしてよね！", "", "ミサキ", 4, 105001, 5, "vo_empress_105001_002", 1, 1, 178);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105001_003", 0, "コ、コイツが幻境竜后…っ\n…正直怖いけど…絶対に逃げないわ\n大人のレディのプライドにかけて\n戦い抜いてやるんだから…！", "", "ミサキ", 4, 105003, 5, "vo_empress_105001_003", 1, 2, 179);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105001_004", 105001, "終わったらデートよ！　だって…\n約束があった方がやる気出るもん♪\nよーし！　大人のレディとして\n最後はエレガントに決めるわよ！", "", "ミサキ", 4, 105002, 5, "vo_empress_105001_004", 1, 3, 180);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105101_001", 0, "なんて重圧かしら…でも、あいにく\n私も伊達に修羅場をくぐってないの\nさあ、かかってきなさい！\n裏の人生経験、見せてあげるわ…♪", "", "ミツキ", 4, 105101, 5, "vo_empress_105101_001", 1, 1, 181);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105101_002", 0, "私は闇医者である前に科学者なの\nあなたたち、実験に協力してくれる\nわよね？　隻眼の悪魔の名は\n伊達じゃないのよ？　覚悟しなさい", "", "ミツキ", 4, 105101, 5, "vo_empress_105101_002", 1, 1, 182);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105101_003", 0, "到底不可能に思える挑戦こそ\n科学者の腕の見せどころなのよ\n青い薔薇のごとく、人の信念が\n起こす奇跡を見せてあげるわ…！", "", "ミツキ", 4, 105101, 5, "vo_empress_105101_003", 1, 2, 183);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105101_004", 105101, "迷いのない言葉をもらったんだもの\n私だってもう、覚悟を決めたわ\nこの先の未来を君と生きていく…\nそのために全力をぶつけるだけよ！", "", "ミツキ", 4, 105101, 5, "vo_empress_105101_004", 1, 3, 184);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105201_001", 0, "私のお友達をいじめるなら\n相手になるわ！\nたとえ魔物に間違えられても\n絶対にここを引かないから！", "", "リマ", 4, 105201, 5, "vo_empress_105201_001", 1, 1, 185);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_105201_002", 0, "ね、ねぇ…\nちょっと聞きたいんだけど\n毛皮もないのにあの姿なのよね？\n風邪引いたりしないのかしら？", 10000, "リマ", 4, 105201, 3, "vo_empress_105201_002", 1, 4002, 186);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105201_003", 0, "ひづめは割れちゃいそうだし…\n毛並みだってボロボロだし…\nでも後ろには彼がいるんだもの\n恋する乙女の負けられない戦いよ！", "", "リマ", 4, 105201, 5, "vo_empress_105201_003", 1, 2, 187);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105201_004", 105201, "私はもう恋する女の子じゃないわ…\n王子様の愛を受け取ったお姫様よ！\n彼が私を守ってくれるように\n私が彼を守ってみせるわ！", "", "リマ", 4, 105202, 5, "vo_empress_105201_004", 1, 3, 188);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105301_001", 0, "どれほど強大な敵であろうと、\n我々【ヴァイスフリューゲル\nランドソル支部】がいれば安心…\nこら！　皆纏まって行動しろー！", "", "モニカ", 4, 105303, 5, "vo_empress_105301_001", 1, 1, 189);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105301_002", 0, "敵戦力は強大無比…だが、\n私たちなら必ず倒せるはずだ！\n白き翼の名のもとに、今こそ\n正義の鉄槌を下してやる！", "", "モニカ", 4, 105301, 5, "vo_empress_105301_002", 1, 1, 190);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105301_003", 0, "これが幻境竜后の底力か…\n名にし負う圧倒的な強さだな…\nだが！　長期戦になろうとも必ずや\n私たちが勝利の旗を掲げるのだ！", "", "モニカ", 4, 105301, 5, "vo_empress_105301_003", 1, 2, 191);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105301_004", 105301, "貴公と一緒ならば\nなんだってできるとも\nさあ、最後の一撃を加えてやろう！", "", "モニカ", 4, 105302, 5, "vo_empress_105301_004", 1, 3, 192);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105401_001", 0, "強そうな相手ばかりですけど\nだからなんだっていうんですか！\nほら、騎士さんも気合い入れて！\n一緒に戦いますよ！", "", "ツムギ", 4, 105401, 5, "vo_empress_105401_001", 1, 1, 193);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_105401_002", 0, "なんか敵に下着姿…っていうか\nほぼ裸みたいな人いません？\n…え？　あれ趣味なんですか？\nあの人の？　…正気ですか？", 10000, "ツムギ", 4, 105403, 3, "vo_empress_105401_002", 1, 4002, 194);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105401_003", 0, "世界を作り変えようなんて\n幻境竜后、絶対許せません…！\nあとその服！　そんなに破いて！\nデザイナーが泣いてますよ！", "", "ツムギ", 4, 105403, 5, "vo_empress_105401_003", 1, 2, 195);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105401_004", 105401, "私と騎士さんの糸は\n絶対に切れません！\nだから…今ここで\nすべてを終わらせましょう！", "", "ツムギ", 4, 105401, 5, "vo_empress_105401_004", 1, 3, 196);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105501_001", 0, "つ、強そうな人たちばっかり…\n逃げたいくらいだけど、\nそれはダメ。先輩をケガさせない\nためにも、私も頑張らなくちゃ！", "", "アユミ", 4, 105503, 5, "vo_empress_105501_001", 1, 1, 197);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105501_002", 0, "私なんかが大それたことを言うのは\n笑われるかも…でも…！\n先輩を守るために、\n世界を守ってみせます…！", "", "アユミ", 4, 105501, 5, "vo_empress_105501_002", 1, 1, 198);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105501_003", 0, "な、なんて大きさ、存在感…！\nまるで私とは真逆の人…\nこうして立ってるだけで、\n私、消えちゃいそうです～っ…！", "", "アユミ", 4, 105503, 5, "vo_empress_105501_003", 1, 2, 199);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105501_004", 105501, "先輩がそばにいてくれる…\nそれだけで勇気が湧いてきて\n前へ進む力がもらえるんです\n行きましょう、先輩！", "", "アユミ", 4, 105502, 5, "vo_empress_105501_004", 1, 3, 200);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105601_001", 0, "雁首並べてよくもまあ…\nこりゃ長丁場になりそうだ\n釣りと同じくじっくり腰を据えて\n勝負しようじゃないか", "", "ルカ", 4, 105601, 5, "vo_empress_105601_001", 1, 1, 201);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105601_002", 0, "世界の危機とあっちゃあ\nアタシたち黄昏時の住人でも\n黙っちゃいられないね！\nひとっ働きさせてもらおうかい！", "", "ルカ", 4, 105601, 5, "vo_empress_105601_002", 1, 1, 202);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105601_003", 0, "へぇ、これが幻境竜后かい…\nたいそうな強さだけど、アタシも\nここで退くわけにはいかないんだ\n心に差した刃に懸けて、いくよ！", "", "ルカ", 4, 105603, 5, "vo_empress_105601_003", 1, 2, 203);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105601_004", 105601, "刀も恋も揃ったアタシは天下無双！\nお前さんが側にいてくれれば、\nどんな巨悪にだって勝てるよ！", "", "ルカ", 4, 105602, 5, "vo_empress_105601_004", 1, 3, 204);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105801_001", 0, "また一緒に、みんなで\nおいしいごはんを食べるために！\nわたしたちは、絶対に負けません！", "", "ペコリーヌ", 4, 105803, 5, "vo_empress_105801_001", 1, 1, 205);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_105801_002", 0, "フレイヤさんだけじゃなく、\n覇瞳皇帝やミロクまで！\n長丁場になりそうです…\n栄養補給はしっかりしましょうね！", 10000, "ペコリーヌ", 4, 105801, 3, "vo_empress_105801_002", 1, 4003, 206);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105801_003", 0, "これが、幻境竜后の力…\nやばいですね。正直、どうやって\n止めればいいのか分かりません\nでもここで引き下がるわけには…っ", "", "ペコリーヌ", 4, 105803, 5, "vo_empress_105801_003", 1, 2, 207);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105801_004", 105801, "あなたの愛情でお腹いっぱいの\n無敵ペコリーヌ参上です☆\nわたしたちの明日を、この世界を\n全力全開で取り戻しましょう！", "", "ペコリーヌ", 4, 105802, 5, "vo_empress_105801_004", 1, 3, 208);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105901_001", 0, "みなさまとのおいしいごはんのため\n負けるわけにはまいりません\n主さま、お背中はお任せください\nわたくしがお守りいたします！", "", "コッコロ", 4, 105903, 5, "vo_empress_105901_001", 1, 1, 209);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105901_002", 0, "敵は強大…ですが、心強い仲間の\nみなさまが一緒でございます\n…全員主さまとお知り合いなのは\n未だに信じられませんが…", "", "コッコロ", 4, 105905, 5, "vo_empress_105901_002", 1, 1, 210);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105901_003", 0, "まだこのような力が…！？\n主さま、ここはお下がりください\nたとえこの身に何があろうと、\nあなただけはお守りいたします…！", "", "コッコロ", 4, 105903, 5, "vo_empress_105901_003", 1, 2, 211);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_105901_004", 105901, "主さまとの絆がある限り\nわたくしは絶対に負けません！\nいついかなるときも、何があろうと\nわたくしが導いてみせます！", "", "コッコロ", 4, 105902, 5, "vo_empress_105901_004", 1, 3, 212);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_106001_001", 0, "また陛下と戦うのね…大丈夫、一番\n大事なものが何なのかは分かってる\n…だから、あたしも負けないわ\n─陛下、よろしくお願いします！", 10000, "キャル", 4, 106001, 3, "vo_empress_106001_001", 1, 4005, 213);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106001_002", 0, "この世界を好き勝手しようだなんて\nそういう連中に人生振り回されるの\nこちとらもううんざりなのよ！\n全員ぶっ飛ばしてやるんだから！", "", "キャル", 4, 106003, 5, "vo_empress_106001_002", 1, 1, 214);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106001_003", 0, "なんなのよあの力、反則でしょ…\nだけどさ、どんなに怖くたって\nあたしはここから退かないわ\n他に行くとこも、ないんだからっ…", "", "キャル", 4, 106003, 5, "vo_empress_106001_003", 1, 2, 215);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106001_004", 106001, "絆の力でパワーアップ、なんて\nガラじゃないと思ってたけど…\n今だけは調子に乗らせてもらうわ\nもう負ける気がしないってねっ！", "", "キャル", 4, 106002, 5, "vo_empress_106001_004", 1, 3, 216);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106101_001", 0, "晶に直してもらって\n天楼覇断剣も新品同然だ！\n気合い入れていくぞオクトー！\nはーっはっはっはー！", "", "ノウェム", 4, 106102, 5, "vo_empress_106101_001", 1, 1, 217);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106101_002", 0, "真那、覚悟しとけよ！\nオマエが積み上げてきた悪事…\nこの大悪党がまとめて\nぶっ壊してやるからな！", "", "ノウェム", 4, 106101, 5, "vo_empress_106101_002", 1, 1, 218);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106101_003", 0, "今までの借り…ここでまとめて\n返してやるって、決めてたんだ\nオマエだけは絶対に、許さない\n…オマエが、どれだけ強くても…っ", "", "ノウェム", 4, 106103, 5, "vo_empress_106101_003", 1, 2, 219);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106101_004", 106101, "大悪党のプリンセス？\nなんだかよくわからないけど──\nとにかく、あの化け物ぶった斬りに\n行くぞ！　ついてこい！", "", "ノウェム", 4, 106102, 5, "vo_empress_106101_004", 1, 3, 220);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106401_001", 0, "絶対に負けられない戦いね\nおいしいごはんと、本当の\nハッピーエンドのために\n気を引き締めていきましょう", "", "シェフィ", 4, 106401, 5, "vo_empress_106401_001", 1, 1, 221);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_106401_002", 0, "ミロク…まだ生きていたのね…！\nあの男は私が相手するわ\n兄さんの分もまとめて、\n今ここで借りを返さないと！", 10000, "シェフィ", 4, 106403, 3, "vo_empress_106401_002", 1, 4004, 222);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106401_003", 0, "こんな力を隠してたなんて…！\n…まだよ。まだ諦めないわ\nどんな方法を使ってでも\nみんなだけは助けてみせる…！", "", "シェフィ", 4, 106401, 5, "vo_empress_106401_003", 1, 2, 223);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106401_004", 106401, "不思議ね…あなたとの思い出で\n全身に力が満ちていくような気持ち\n…私たちが紡いできた絆を\n幻境竜后に見せてやりましょう", "", "シェフィ", 4, 106402, 5, "vo_empress_106401_004", 1, 3, 224);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106501_001", 0, "おまえら、ケンカ売りたいんだろ？\nこの世界そのものに！\nならこっち向けよ。喧嘩屋のオレが\nまとめて買ってやるぜ！", "", "カヤ", 4, 106501, 5, "vo_empress_106501_001", 1, 1, 225);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106501_002", 0, "オレがドラゴン族なのも、\nこんな力を持ってるのも…きっと\n今日、この時のためだったんだ\nそうだろ？", "", "カヤ", 4, 106501, 5, "vo_empress_106501_002", 1, 1, 226);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106501_003", 0, "ウソだろ…オレが竦んじまってる…\nアイツのあの赤い眼から、眼を\nそらすんじゃねぇ…！　ドラゴン族\nのケンカ最強は…オレ様だろッ…！", "", "カヤ", 4, 106503, 5, "vo_empress_106501_003", 1, 2, 227);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106501_004", 106501, "自分の力に、ずっとビビッてた\nでも今は何よりこの力を頼もしく\n感じるぜ。テメェをぶっ倒し…\n明日を迎えるための力がなァ！", "", "カヤ", 4, 106501, 5, "vo_empress_106501_004", 1, 3, 228);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106601_001", 0, "どきやがれです！　最強ギャングが\nおまえのシマ分捕りにきたですよ！\nこんだけ仲間がいりゃ楽勝ですね♪\n尻尾巻いて逃げ出しやがれです！！", "", "イノリ", 4, 106603, 5, "vo_empress_106601_001", 1, 1, 229);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106601_002", 0, "あっちもゾロゾロつれてきやがり\nましたね…へんっ、このあたしが\nビビビビるとでもおお思うですか\n…お、お兄さん、どどどこです？", "", "イノリ", 4, 106601, 5, "vo_empress_106601_002", 1, 1, 230);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106601_003", 0, "…！　あたしと同じドラゴン族？\nボスをプリンセスナイトに従えて\nたとか…へんっ、信じねーです！\nまあボスより性悪そ…ぴゃああっ", "", "イノリ", 4, 106603, 5, "vo_empress_106601_003", 1, 2, 231);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106601_004", 106601, "ふっふっふ～ん！　熱い力が\nどんどん溢れてくるですよっ！\nさあ、懲らしめてやるですっ！\nおしりペンペンですよ！", "", "イノリ", 4, 106602, 5, "vo_empress_106601_004", 1, 3, 232);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106701_001", 0, "ふふっ、強そうな子がいっぱいだね\nそれじゃあ、誰が一番か決めよっか\nヴィーちゃんのプリンセスナイトで\n歴代最強は誰なのかを、ね♪", "", "ホマレ", 4, 106701, 5, "vo_empress_106701_001", 1, 1, 233);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106701_002", 0, "ヴィーちゃんてば、そんな子たちと\n一緒にいるほうが楽しいんだ～？\nじゃ、私たちも見せつけないとだね\n遠慮なくやっちゃおう☆　あははっ", "", "ホマレ", 4, 106701, 5, "vo_empress_106701_002", 1, 1, 234);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106701_003", 0, "これが、ヴィーちゃんの本気…\nとってもとってもすごいなぁ\n怖がりだからこそ、そんなに\n強くなれちゃったのかな…", "", "ホマレ", 4, 106703, 5, "vo_empress_106701_003", 1, 2, 235);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106701_004", 106701, "残念だけど、ヴィーちゃん…\nもうゲームオーバーみたいだよ\nあなたとのどんなゲームも私には…\n全部ドキドキして、楽しかったな", "", "ホマレ", 4, 106702, 5, "vo_empress_106701_004", 1, 3, 236);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106801_001", 0, "毎度、予想を超える困難ばかり\n押し寄せてくるんだからさ～\nま、アタシと少年が居る以上、\n好きにはさせないよ、ってね！", "", "ラビリスタ", 4, 106802, 5, "vo_empress_106801_001", 1, 1, 237);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_106801_002", 0, "よりによって真那まで相手かぁ…\nこりゃ一筋縄じゃいかなそうだ\n誰に対応するかは任せるけど、\n真那を相手取るなら頼ってよ", 10000, "ラビリスタ", 4, 106801, 3, "vo_empress_106801_002", 1, 4005, 238);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106801_003", 0, "当然、奥の手も用意してくるよね\n次から次へと用意周到だこと…\nとはいえこっちも負けられない\nこの難局の突破口を探すとしよう！", "", "ラビリスタ", 4, 106801, 5, "vo_empress_106801_003", 1, 2, 239);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_106801_004", 106801, "七冠…しかも幻境竜后が相手なら\n手は抜けそうにもないね\nはは、でもアタシたちならきっと\n乗り越えられーる！　だよね少年♪", "", "ラビリスタ", 4, 106802, 5, "vo_empress_106801_004", 1, 3, 240);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_107001_001", 0, "真那…ふふ、こんなところで相対\nすることになるとは。いつぞやの\n借り、返してあげますよ。用意は\nいいですね？　マサキも、貴方も", 10000, "ネネカ", 4, 107001, 3, "vo_empress_107001_001", 1, 4005, 241);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_107001_002", 0, "数で私たちを圧倒しようなど…\n底の浅い戦略ですね。返り討ちに\nしてあげましょう…この世界を\nまだ失うわけにはいきませんから", "", "ネネカ", 4, 107001, 5, "vo_empress_107001_002", 1, 1, 242);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_107001_003", 0, "この力…計算外ではありますが\nそれは予想外という意味では\nありません。ええ、楽しみましょう\n不可能を解く、方程式の探求を", "", "ネネカ", 4, 107001, 5, "vo_empress_107001_003", 1, 2, 243);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_107001_004", 107001, "特等席で観察させてもらいましょう\n貴方の『心』という変数が\n『レジェンドオブアストルム』に\nどのような影響を与えるのかを…", "", "ネネカ", 4, 107002, 5, "vo_empress_107001_004", 1, 3, 244);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_107101_001", 0, "クリスティーナさんのご登場だよ☆\nあっははは……☆　またとない宴だ\n心行くまで愉しもうじゃあないか\n血で血を洗うダンス…滾るな♪", "", "クリスティーナ", 4, 107101, 5, "vo_empress_107101_001", 1, 1, 245);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_107101_002", 0, "真那さまがお出ましか…ワタシは\n本当に運がいいと見える♪　本気で\n刃を交える機会が巡ってくるなど\n願ってもない幸運だよ☆", 10000, "クリスティーナ", 4, 107101, 3, "vo_empress_107101_002", 1, 4005, 246);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_107101_003", 0, "…ここで退くなど興冷めだろう？\nたとえ足が竦んだとしても…退屈に\n食われるよりもよほどいい！\n最後まで愉しみつくしてやるさ…☆", "", "クリスティーナ", 4, 107103, 5, "vo_empress_107101_003", 1, 2, 247);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_107101_004", 107101, "誤算だったなあ、『幻境竜后』\n他の者ならいざ知らず…\nキサマを殺せる唯一の力\n手にしたのはこの『誓約女君』だ！", "", "クリスティーナ", 4, 107102, 5, "vo_empress_107101_004", 1, 3, 248);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_110801_001", 0, "ざーす。世界を救う系の光バイトで\n来たんすけど…あ、説明とかは\n大丈夫っす。慣れてるんでノリで\n入れます─おのれ世界の敵め！", "", "クロエ", 4, 110801, 5, "vo_empress_110801_001", 1, 1, 249);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_110801_002", 0, "なっつ、狐のねえさんいるじゃん\nまだ現役で悪モンやってたんだ\nてか中ボスポジに降格してるくね？\n世界の敵界隈、意外とせちがれーな", 10000, "クロエ", 4, 110801, 3, "vo_empress_110801_002", 1, 4005, 250);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_110801_003", 0, "なんかヤベーの出てきたな…\nこのカンジ、若干最悪っていうか\nぶっちゃけ流れ変わったくない？\nこっから捲るのは…結構ダルいわ", "", "クロエ", 4, 110803, 5, "vo_empress_110801_003", 1, 2, 251);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_110801_004", 110801, "ちょ、聞いて敵、ウケんだけど\nなんかうち主人公だったみたいだわ\n山場でヒロインに力託され系のやつ\nてわけで、勝ち確いただきでーす", "", "クロエ", 4, 110802, 5, "vo_empress_110801_004", 1, 3, 252);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_110901_001", 0, "ちぇるーん☆　ボス敵のみんな～！\n初めまして＆お久しブリリアント！\n世界の美少女ちえるんでっす！\n今からぼっこぼこにしてあげるね！", "", "チエル", 4, 110901, 5, "vo_empress_110901_001", 1, 1, 253);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_110901_002", 0, "クリスＰの敵はカルミナの敵！\nカルミナの敵はなかよし部の敵！\nツアー全通めざして戦います！\n現場の平和はチエルが守る！", "", "チエル", 4, 110901, 5, "vo_empress_110901_002", 1, 1, 254);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_110901_003", 0, "あ、あのう…ヤバくないです？\n敵のねえさん、急に年末歌合戦の\nラスボス衣装みたくなりましたけど\nえ、どーしよ…揚げます白旗？", "", "チエル", 4, 110903, 5, "vo_empress_110901_003", 1, 2, 255);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_110901_004", 110901, "世界の敵さん、ごめんちゃい！\nなんか愛だか絆だかの超理論的な\nアレでチエル覚醒しちゃいました！\nちぇるっと終わらせてあげますね！", "", "チエル", 4, 110902, 5, "vo_empress_110901_004", 1, 3, 256);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_111001_001", 0, "世界の危機だって？　何度目だね？\nざまあみろだよ、勝手に滅べば…\nなに、地球の危機？　この箱庭の\n話ではなく？　何ソレ一大事！", "", "ユニ", 4, 111001, 5, "vo_empress_111001_001", 1, 1, 257);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_111001_002", 0, "お、おい…敵が多すぎないか…？\n端の方でわちゃわちゃしてるだけの\n数合わせ要員として来たのだが…\nどういう事だ、聞いてた話と違うぞ", "", "ユニ", 4, 111001, 5, "vo_empress_111001_002", 1, 1, 258);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_111001_003", 0, "あばば…なんだ、あの奇怪な姿は…\nあれが理系をこじらせた者の末路か\n宇宙暗黒理系女…どうしてあんなに\nなるまで放っておいたんだ…", "", "ユニ", 4, 111003, 5, "vo_empress_111001_003", 1, 2, 259);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_111001_004", 111001, "はん、驕ったな理系の女王よ\n世界は君が思うほど四角くない\n高機能計算機の弾いた数字ごときで\nぼくと彼の行間までは測れまいよ！", "", "ユニ", 4, 111002, 5, "vo_empress_111001_004", 1, 3, 260);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_118001_001", 0, "ですからわたくしは商人で、\n戦いなどは不向き…などと\n言ってる場合ではありませんわね！\n参りますわよ、我が陛下のために！", "", "クレジッタ", 4, 118001, 5, "vo_empress_118001_001", 1, 1, 261);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_118001_002", 0, "ああもうはあもう、あっちこっち\n滅茶苦茶にしてくださってからに！\n復興費用の賠償はどなたに\n請求すればよろしいのかしら！？", "", "クレジッタ", 4, 118003, 5, "vo_empress_118001_002", 1, 1, 262);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_118001_003", 0, "でっか！？　でっっっっか！！！\n幻境竜后でしたかしら！？\nなんなんですのあの高層建築な方、\n建築基準法違反ですわよ～っ！？", "", "クレジッタ", 4, 118003, 5, "vo_empress_118001_003", 1, 2, 263);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_118001_004", 118001, "ホーッホッホッホ！　幻境竜后さん\n貴方にはいらっしゃるのかしら！\n利害でなくその理想のために\n命を賭ける、真実の忠臣が！", "", "クレジッタ", 4, 118002, 5, "vo_empress_118001_004", 1, 3, 264);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_118101_001", 0, "恐ろしくて強そうな音が…たくさん\nでも…きっと、大丈夫。あなたや、\nミソラちゃん…みんなが一緒で…\nあたたかい音も、たくさんだもの…", "", "ランファ", 4, 118101, 5, "vo_empress_118101_001", 1, 1, 265);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_118101_002", 0, "緊張、してる…？　そ、それなら、\nわたしに、任せて…わたし、歌を、\n歌うわね…聴けばきっと、いつも\n通りの力を、出せると思うから…", "", "ランファ", 4, 118101, 5, "vo_empress_118101_002", 1, 1, 266);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_118101_003", 0, "お、音と声が、すごい…\nなんて…なんて恐ろしいのかしら…\n…？　で、でも…この音。\n幻境竜后も、恐怖…している…？", "", "ランファ", 4, 118103, 5, "vo_empress_118101_003", 1, 2, 267);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_118101_004", 118101, "わたしの歌が、どれほど役立つかは\nわからない…そ、それでもっ、\nあなたの力になりたいの…だから\nわたし、精一杯、歌うわね…", "", "ランファ", 4, 118102, 5, "vo_empress_118101_004", 1, 3, 268);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_118201_001", 0, "わー、ミロクさんや覇瞳皇帝さんも\nいるじゃないですか★\nそれじゃあわたしのガトリングで\nご挨拶といきましょっか♪", 10000, "ミソラ", 4, 118201, 3, "vo_empress_118201_001", 1, 4005, 269);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_118201_002", 0, "騎士さんと力を合わせればどんな\n敵もほにゃららら～★　って感じで\nなんとかなると思うんですよねー\nほら、主人公補正ってやつで♪", "", "ミソラ", 4, 118201, 5, "vo_empress_118201_002", 1, 1, 270);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_118201_003", 0, "復讐って、イイコトですかね？\n悪いコトですかね？まぁとりあえず\nぶっ壊してから考えましょうか\nね、幻境竜后さん─", "", "ミソラ", 4, 118202, 5, "vo_empress_118201_003", 1, 2, 271);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_118201_004", 118201, "騎士さんに選んでもらっちゃいまし\nたし、いらない縁とはバイバイした\nいんですよねー♪　ってわけで、\nここで終わりにさせてもらいます★", "", "ミソラ", 4, 118202, 5, "vo_empress_118201_004", 1, 3, 272);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_118501_001", 0, "みなさんの力を信じて、\n私も全力でサポートします\n連携と創意工夫があれば、きっと\nこの難局も乗り越えられます！", "", "カリン", 4, 118501, 5, "vo_empress_118501_001", 1, 1, 273);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_118501_002", 0, "過去最大級の強敵が現れました！\nギルド管理協会を代表して…\nあなたに討伐を依頼します！\n報酬はお望みのままに、ですよ♪", "", "カリン", 4, 118502, 5, "vo_empress_118501_002", 1, 1, 274);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_118501_003", 0, "…っ。さすがの強敵ですね…\nだからこそ、焦りは禁物…です\nあらゆる事態を想定して、ギルドの\nみなさんを支援するのが私の仕事…", "", "カリン", 4, 118503, 5, "vo_empress_118501_003", 1, 2, 275);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_118501_004", 118501, "あなたと共に進めば\nどんな壁も越えられます\n私の、大切な人の無事を信じて…\n今こそ全力を尽くします！", "", "カリン", 4, 118502, 5, "vo_empress_118501_004", 1, 3, 276);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_118601_001", 0, "あんな奴らを野放しにしてたら\nこの世界が滅茶苦茶にされちゃう！\nでもまぁこれはこれでチャンスよ♪\n最っ高の悪戯の標的にしてあげる！", "", "ネビア", 4, 118601, 5, "vo_empress_118601_001", 1, 1, 277);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_118601_002", 0, "私はただのガイド妖精、みんなに\n比べれば大した力も持ってない…\nでも悪戯妖精なりの意地があんのよ\nあいつらに一泡吹かせてやるわ♪", "", "ネビア", 4, 118601, 5, "vo_empress_118601_002", 1, 1, 278);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_118601_003", 0, "幻境竜后、なんて力の持ち主なの\n正直きっついわ…でもまだやれる\n私はデータよ、壊れたって\nあんたを守る壁くらいにはなれる…", "", "ネビア", 4, 118603, 5, "vo_empress_118601_003", 1, 2, 279);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_118601_004", 118601, "覚悟しなさいっ！\n出来損ないの悪戯妖精をなめたら\n痛い目に遭うって教えてあげる\nさぁ、最高のショーの始まりよ！", "", "ネビア", 4, 118602, 5, "vo_empress_118601_004", 1, 3, 280);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_122301_001", 0, "むー！　いたずらっこの暴れんぼ\nさんたちは、ヴァンピィちゃんが\nきつーくおしおきしちゃうよ！\n真祖のおつとめですから！", "", "ヴァンピィ", 4, 122303, 5, "vo_empress_122301_001", 1, 1, 281);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_122301_002", 0, "けんぞくはヴァンピィちゃんの\n背中に隠れてなさいっ。え？\n背中を守りたい？　うん、それなら\nよろしい！　一緒だよ、けんぞく！", "", "ヴァンピィ", 4, 122302, 5, "vo_empress_122301_002", 1, 1, 282);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_122301_003", 0, "幻境竜后？　ふーんだ！\nベスちゃんのほーが、ずーっと\n強くてカッコいいですし！\nいくよっ、けんぞくぅ！", "", "ヴァンピィ", 4, 122303, 5, "vo_empress_122301_003", 1, 2, 283);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_122301_004", 122301, "ここはみんなの『いばしょ』！\n壊しちゃうなんて、許さないもん\nヴァンピィちゃん、本気で怒ったよ\nやっちゃうよ、けんぞく！", "", "ヴァンピィ", 4, 122302, 5, "vo_empress_122301_004", 1, 3, 284);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_123001_001", 0, "ほら、あんたは余計な心配しないの\nあいつらに好き勝手させないように\n全力でぶつかっていくだけよ\nあたしたちの未来のためにね♪", "", "アメス", 4, 123002, 5, "vo_empress_123001_001", 1, 1, 285);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_123001_002", 0, "…あの連中も強くてやばいけど…\n一番やばいのは、こんなにたくさん\n女の子の知り合いがいる\nあんたかもしれないわね…", "", "アメス", 4, 123001, 5, "vo_empress_123001_002", 1, 1, 286);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_123001_003", 0, "なんて相手なの…さすがに想定を\n超えてるわよ…こんなの卑怯よね\nだからってここで逃げやしないわよ\nせめて、あんたを守るくらいは…！", "", "アメス", 4, 123003, 5, "vo_empress_123001_003", 1, 2, 287);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_123001_004", 123001, "敵がどれだけ強くたって関係ないわ\nあんたの行く道はあたしが照らす\n迷ったらあたしを見なさい\nどこまでだって導いてあげる！", "", "アメス", 4, 123002, 5, "vo_empress_123001_004", 1, 3, 288);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_123301_001", 0, "『レギオンウォー』思い出すな～\nあん時は敵側だったけどー\n今回は騎士きゅんたちの隣で\nネアおねえちゃんもがんばるぞ～♡", "", "ネア", 4, 123301, 5, "vo_empress_123301_001", 1, 1, 289);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_123301_002", 0, "だる～、激ヤバなテキばっかじゃん\n騎士きゅんパワー充電しねーと\nおねえちゃんもギリギリかもー\nとりま、ちゅっちゅ♡　してい？", "", "ネア", 4, 123301, 5, "vo_empress_123301_002", 1, 1, 290);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_123301_003", 0, "激ヤバドラゴン、ガチしんどー…\nま、だからって負ける気ねーけど\nこーゆう時こそ、スライムの\n粘り強さの見せ所っしょ～　ね♪", "", "ネア", 4, 123303, 5, "vo_empress_123301_003", 1, 2, 291);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_123301_004", 123301, "ンフフフフ～♪　今のアタシ、\n騎士きゅんと一心同体ってやつ～？\nめちゃめちゃアガるわ～♪\n愛の力パねぇ～♡", "", "ネア", 4, 123302, 5, "vo_empress_123301_004", 1, 3, 292);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_126401_001", 0, "ビーッ！　ビーッ！\nあっちもこっちもそっちも\n強そうな人たちでいっぱいですっ！\nセンサーが壊れちゃいそう～っ！", "", "クローチェ", 4, 126401, 5, "vo_empress_126401_001", 1, 1, 293);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_126401_002", 0, "世界が大変なことになってますっ！\nでもわたしたちは今までだって、\n大変な戦いを乗り越えてきましたっ\nきっと…ううん、絶対勝てますっ！", "", "クローチェ", 4, 126401, 5, "vo_empress_126401_002", 1, 1, 294);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_126401_003", 0, "ビビービビビーッ！　…ひゃあっ！\nセンサーが壊れちゃいました…！\nしかも、照準が震えちゃって…\n…これが…この感情が、恐怖…？", "", "クローチェ", 4, 126403, 5, "vo_empress_126401_003", 1, 2, 295);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_126401_004", 126401, "今のわたしたちに、怖いものなんて\nありませんっ！　敵さんがどんなに\n強くても…わたしとナイトさんの\n特別なパワーは、もっと強いです！", "", "クローチェ", 4, 126402, 5, "vo_empress_126401_004", 1, 3, 296);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_126501_001", 0, "ジオ・テオゴニアの姫として\nこの星に生きる一個として\nこれ以上の蹂躙を許すわけには\nいきません。そうですね？　騎士", "", "ライラエル", 4, 126501, 5, "vo_empress_126501_001", 1, 1, 297);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_126501_002", 0, "穢らわしい、色狂いの山羊めが\n我が従僕を傀儡としてくれた借り、\n兆倍──否、京倍にして\n返してくれようぞ。崩雷夜天！", 10000, "ライラエル", 4, 126506, 3, "vo_empress_126501_002", 1, 4002, 298);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_126501_003", 0, "幻境竜后。迷いなく、圧倒的な力で\nわたしたちの調和を滅しようとする\nそんな力を、認めたくはないのに…\nなんて、困難な戦いなのでしょう…", "", "ライラエル", 4, 126503, 5, "vo_empress_126501_003", 1, 2, 299);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_126501_004", 126501, "この星には、あなたがいる…\n悪辣な侵略者と戦う理由など、\nただそれだけで十分です\n守りましょう。わたしたちの世界を", "", "ライラエル", 4, 126502, 5, "vo_empress_126501_004", 1, 3, 300);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_127701_001", 0, "あそこにヴルムを傷つけた人が…！\n…騎士さん、絶対勝ちましょうね\nあの人たちのやったこと、私\n絶対ぜったい許しませんから！", 10000, "リンド", 4, 127701, 3, "vo_empress_127701_001", 1, 4002, 301);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_127701_002", 0, "騎士さんたちと出会えたこの世界を\n悪いことになんか使わせません\n作り物だなんて信じられませんけど\n失っちゃいけないものはわかります", "", "リンド", 4, 127701, 5, "vo_empress_127701_002", 1, 1, 302);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_127701_003", 0, "まだこんな力が残ってるの…！？\n考えなきゃ、私にできること…\n何か…何かないの…！？\nまた私、何もできないの…？", "", "リンド", 4, 127703, 5, "vo_empress_127701_003", 1, 2, 303);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_127701_004", 127701, "あなたが側にいてくれるから、\n私もこうして戦えます\nチョロいって言われてもいいです\n私にとって、大切なひとですから", "", "リンド", 4, 127702, 5, "vo_empress_127701_004", 1, 3, 304);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_127801_001", 0, "…正直、サボりとかじゃなくて…\nぜんぜん身体はきついです。でも…\n姉貴やみんなと過ごすこの世界は\n誰にも壊させやしませんから…！", "", "ヴルム", 4, 127801, 5, "vo_empress_127801_001", 1, 1, 305);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_127801_002", 0, "騎士さん…アルシャトのこと\nあたしにも一発殴らせてください\nふざけた真似してくれたお礼…\n倍にして返してやりますよ", 10000, "ヴルム", 4, 127801, 3, "vo_empress_127801_002", 1, 4002, 306);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_127801_003", 0, "冗談きついです、こんなの…\n勝てっこないじゃないですか\nあたしだってドラゴン族なのに\nこれほどまでに差があるだなんて…", "", "ヴルム", 4, 127803, 5, "vo_empress_127801_003", 1, 2, 307);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_127801_004", 127801, "もう後先考えずにいきますよ\n面倒見てくれる人がここにいるので\nあたしと騎士さんが揃えば\n無敵だってとこ見せてやります", "", "ヴルム", 4, 127802, 5, "vo_empress_127801_004", 1, 3, 308);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_129001_001", 0, "覇瞳皇帝…わたしの邪魔をするなら\nかつてのように、消去するだけ\nミロクも…わたしを草野優衣の\n複製と呼んだこと、後悔させてやる", 10000, "エリス", 4, 129001, 3, "vo_empress_129001_001", 1, 4005, 309);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_129001_002", 0, "管理者の座は失っても\nわたしの意志は揺らがない…\n騎士クンの物語を紡ぐために…\nそれが、わたしの全てだから", "", "エリス", 4, 129001, 5, "vo_empress_129001_002", 1, 1, 310);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_129001_003", 0, "これが七冠、幻境竜后の全力…\n管理者だったかつてのわたしを、\n超えるほどの脅威…でも、\n騎士クンだけは、守ってみせる…", "", "エリス", 4, 129003, 5, "vo_empress_129001_003", 1, 2, 311);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_129001_004", 129001, "孤独も絶望も越えてきた\nもうどんな闇にも迷わない\n騎士クンが隣にいる限り\nわたしは、負けない", "", "エリス", 4, 129002, 5, "vo_empress_129001_004", 1, 3, 312);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_129601_001", 0, "リアを──媛を、傷つけたひとたち\n笑ってられるのも今だけです──\nアルラウネの棘の鋭さ、\n教えてあげますから──", "", "アネモネ", 4, 129601, 5, "vo_empress_129601_001", 1, 1, 313);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_129601_002", 0, "騎士のひと──背中は、任せます\n貴方のこと、\n媛と同じくらい、信じてるので──\n自分でも、びっくりですけど", "", "アネモネ", 4, 129601, 5, "vo_empress_129601_002", 1, 1, 314);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_129601_003", 0, "私、ずっと抗ってきたんです\nそのために、強くなったはず──\nだから──諦めたく、ないです…", "", "アネモネ", 4, 129603, 5, "vo_empress_129601_003", 1, 2, 315);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_129601_004", 129601, "体が熱くて、思考がまとまらなくて\nなのに負ける気がしない──なんて\nよくわからないです。どうしてか、\n後で教えてください──騎士のひと", "", "アネモネ", 4, 129601, 5, "vo_empress_129601_004", 1, 3, 316);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_129701_001", 0, "難敵強敵揃い踏みなれど\nわっちらが退く理はありんせん\n騎士殿や、手を携えて此度の争乱\n鎮めて見せましょう也", "", "ネフィ＝ネラ", 4, 129701, 5, "vo_empress_129701_001", 1, 1, 317);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_129701_002", 0, "今のわっちが萎弱であろうとて\n貴様等如き梟悪に斃される訳には\nゆかぬ也。再び足甲を舐めさせ\n地に臥すまで仕置きを致しんしょう", "", "ネフィ＝ネラ", 4, 129701, 5, "vo_empress_129701_002", 1, 1, 318);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_129701_003", 0, "我が矜持『不退転』─如何なる敵で\nあろうとも揺らぐ仕儀はなし。斯様\nな邪竜程度、退けむと思い侍りしが\n─難儀な由、残念至極─…", "", "ネフィ＝ネラ", 4, 129703, 5, "vo_empress_129701_003", 1, 2, 319);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_129701_004", 129701, "参りまする也、騎士殿や\n懼るること等何一つ御座りんせん\n唯わっちらの勇儀を以て、此の星の\n明日を再び…掌中に致しんしょう", "", "ネフィ＝ネラ", 4, 129702, 5, "vo_empress_129701_004", 1, 3, 320);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_130001_001", 0, "─おや、フレイヤじゃないか\nずいぶん様変わりしたようだが\n今の方がアタシとしちゃ好みだね\nお礼参りのしがいもあるってもんさ", 10000, "ヤマト", 4, 130001, 3, "vo_empress_130001_001", 1, 4003, 321);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_130001_002", 0, "…フゥン？　あっちもこっちも\n『王家の装備』を持ってるらしいね\n宝の山ってのはこのことかい\nまとめて搔っ攫ってやろうかね…！", "", "ヤマト", 4, 130001, 5, "vo_empress_130001_002", 1, 1, 322);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_130001_003", 0, "ちっ…、幻境竜后つったかい\n世界を奪おうってのも冗談じゃ\nなさそうだ。…ワカナ、フブキ…\nお前たちだけでも、逃げな…", "", "ヤマト", 4, 130003, 5, "vo_empress_130001_003", 1, 2, 323);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_130001_004", 130001, "アタシらの住み家を奪おうだぁ？\nハッ、笑わせてくれるね\n盗賊は盗むモンであって、\n盗まれるモンじゃあないンだよ！", "", "ヤマト", 4, 130002, 5, "vo_empress_130001_004", 1, 3, 324);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_130101_001", 0, "つ、強そうな人たちがたくさん…\nなのに姉さんもフブキちゃんも\nやる気満々だし…\nわたし、どうすればいいのぉ～っ", "", "ワカナ", 4, 130101, 5, "vo_empress_130101_001", 1, 1, 325);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_130101_002", 0, "きっと、長期戦になりますよね…\nあ、あの…ご飯、食べませんか？\nお腹が空くといけないと思って、\n作ってきたので…よろしければっ", "", "ワカナ", 4, 130101, 5, "vo_empress_130101_002", 1, 1, 326);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_130101_003", 0, "む…むりっ！　無理ですよ～っ！\nあんなおっきいドラゴンなんて、\n勝てるわけないじゃないですかっ\nに、逃げちゃいましょ、ねっ…！？", "", "ワカナ", 4, 130103, 5, "vo_empress_130101_003", 1, 2, 327);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_130101_004", 130101, "と、盗られるぐらいなら盗るのが\n【バンディ・シスターズ】流ですっ\n騎士さん、わたしたちの未来を\n掴み取りにいきましょう…っ！", "", "ワカナ", 4, 130102, 5, "vo_empress_130101_004", 1, 3, 328);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_130201_001", 0, "だる～、ささっと片付けてきてよ～\nムリ？　知ってる～だってザコザコ\nお兄さんだもんね♪　しょーがない\n助けてあげよっかな～？きゃはは♡", "", "フブキ", 4, 130201, 5, "vo_empress_130201_001", 1, 1, 329);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_130201_002", 0, "あの陰気ダサダサメガネさー、\n仲間集めてチョーシ乗ってねー？\nザコは何匹集まったってザコだって\nフブキちゃんが教えてあげまーす♪", "", "フブキ", 4, 130201, 5, "vo_empress_130201_002", 1, 1, 330);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_130201_003", 0, "ふぇぇ…まじムリ、アイツムリ～！\n全然ラスボスってカンジじゃん！？\nぼくお家かえるぅ～っ！\nお兄さんも一緒にかえろっ、ねっ？", "", "フブキ", 4, 130203, 5, "vo_empress_130201_003", 1, 2, 331);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_130201_004", 130201, "お兄さん、やる気漲っちゃってる？\nだよねー、世界が滅んじゃったら\nぼくとも永遠のお別れなんだし？\n必死になるのもトーゼンっしょ～♡", "", "フブキ", 4, 130202, 5, "vo_empress_130201_004", 1, 3, 332);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_130901_001", 0, "はわっ！？　すっごくすっごく\n悪そうな人達いっぱいですますぅ！\nかばばん君、警備員モードです！\nぴっぴーーーー！", "", "クルル", 4, 130901, 5, "vo_empress_130901_001", 1, 1, 333);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_130901_002", 0, "この戦いが終わったら、みなさんと\nパークで凱旋パレードですぅ♪\n…ふぇっ？\n気が早いですますか？", "", "クルル", 4, 130901, 5, "vo_empress_130901_002", 1, 1, 334);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_130901_003", 0, "はわわっ！　幻境竜后さん、\n強そうすぎですっ…でもっ！\nやっと再建したパークも世界も\nぜったい壊させないですよ～っ！", "", "クルル", 4, 130903, 5, "vo_empress_130901_003", 1, 2, 335);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_130901_004", 130901, "ヒーローさんのこと、\nクルルの全部でお助けしますです！\nジオ・テオゴニアでも、どんな世界\nでも…ずっと、ず～っとですっ！", "", "クルル", 4, 130902, 5, "vo_empress_130901_004", 1, 3, 336);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_132301_001", 0, "なっなんなのよこいつらっ！\nダーリンとの恋路を邪魔する気…？\nそんなことさせないわ…だって、\n二人の恋はエターナルですからっ！", "", "ルイズマリー", 4, 132301, 5, "vo_empress_132301_001", 1, 1, 337);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_132301_002", 0, "愛情×愛情＝無限大…\n遂に錬金術の神髄に辿り着いたわ…\nさあ…お見舞いしてやりましょう！\n私とダーリンの究極錬成をっ！", "", "ルイズマリー", 4, 132301, 5, "vo_empress_132301_002", 1, 1, 338);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_132301_003", 0, "あ、あなたがどんなに強くても、\n私は逃げないわ！　ダーリンに\nちょっかいかける奴は絶対に\n許さないって決めてるから…っ！！", "", "ルイズマリー", 4, 132303, 5, "vo_empress_132301_003", 1, 2, 339);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_132301_004", 132301, "悪いけど速攻で終わらせちゃうわ！\n早く帰ってダーリンと心行くまで\n破廉恥な乳繰り合い…じゃなくて！\n愛を確かめ合うんだからっ！", "", "ルイズマリー", 4, 132302, 5, "vo_empress_132301_004", 1, 3, 340);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_132401_001", 0, "わわっ、敵がいっぱい！\nこれがクワガタだったら最高…よし\n新種のクワガタって事にしちゃお！\nあははっ！　待て待て～っ！！", "", "イロハ", 4, 132401, 5, "vo_empress_132401_001", 1, 1, 341);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_132401_002", 0, "あはは、まだまだ出てくるね～！\nなら新しい技いっぱい\n試しちゃおっか…さあ、いくよ！\n──イスルギ流奥義っ！！", "", "イロハ", 4, 132401, 5, "vo_empress_132401_002", 1, 1, 342);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_132401_003", 0, "あのおねーさんもなかなか良いツノ\n持ってるねえ♪　イロハが勝ったら\nルイちゃんと二人でクワガタ相撲\nごっこやってもらおっと！", "", "イロハ", 4, 132401, 5, "vo_empress_132401_003", 1, 2, 343);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_132401_004", 132401, "おねーさんがどんなに強くたって\nイロハは絶対に負けない！\nおじちゃんが見ててくれてる時の\nイロハは、サイキョーなんだから！", "", "イロハ", 4, 132402, 5, "vo_empress_132401_004", 1, 3, 344);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_132501_001", 0, "いや無理無理、戦いとか苦手過ぎる\n…でも君となら、奇跡起こせるかも\n…うわやば、今の忘れて\n若者みたいなこと言っちゃったよ…", "", "ソノ", 4, 132501, 5, "vo_empress_132501_001", 1, 1, 345);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_132501_002", 0, "敵、まだいっぱいいるじゃん…\nはあ…残業したくないけど頑張るか\n全部終わったら君からのマッサージ\n期待しとくから、ね", "", "ソノ", 4, 132501, 5, "vo_empress_132501_002", 1, 1, 346);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_132501_003", 0, "はあ…はあ…幻境竜后だっけ？\nルイちゃんの錬金術より\n出鱈目な強さだね…！\nでもまだまだ諦めない…いくよ！", "", "ソノ", 4, 132503, 5, "vo_empress_132501_003", 1, 2, 347);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_132501_004", 132501, "こんなに強い敵が相手でも\n諦めなきゃ勝てるんだって\n教えてくれたのは君だよ\nふふ…ありがとね、若者♪", "", "ソノ", 4, 132502, 5, "vo_empress_132501_004", 1, 3, 348);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_133001_001", 0, "うーわ。あっちもこっちも\nボス級だらけじゃないですか\nま、ヴァイオレット姫には\n指一本触れさせませんけどね", "", "グレイス", 4, 133001, 5, "vo_empress_133001_001", 1, 1, 349);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_133001_002", 0, "リーザ…今度こそ、決着の時ね\nいくら頭数を揃えても私は…いえ\n私と騎士氏は絶対に負けないわ\nこの槍で、冥界に送り返してあげる", 10000, "グレイス", 4, 133003, 3, "vo_empress_133001_002", 1, 4001, 350);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_133001_003", 0, "ぐっ…圧倒的ですね『幻境竜后』\nですが…決してあきらめません\n私には、生きていてほしい人が\nたくさんいますので…！", "", "グレイス", 4, 133003, 5, "vo_empress_133001_003", 1, 2, 351);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_133001_004", 133001, "とてつもない強敵を前にしてるのに\nまるで恐怖心を感じません…\n…恋とは、心霊現象よりも\n不思議なものらしいですよ", "", "グレイス", 4, 133002, 5, "vo_empress_133001_004", 1, 3, 352);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_133101_001", 0, "恐るべき方々ばかりです…\nですがわたくしは絶対に退きません\nジオ・ニヴルヘルの姫として\nこの世界を守ると決めたのです！", "", "ヴァイオレット", 4, 133101, 5, "vo_empress_133101_001", 1, 1, 353);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_133101_002", 0, "リーザ…どうしてもわたくしたちの\n前に立ちはだかるというのですね\nならばわたくしも覚悟を決めました\nこの手であなたを、倒します…！", 10000, "ヴァイオレット", 4, 133101, 3, "vo_empress_133101_002", 1, 4001, 354);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_133101_003", 0, "これが、彼女の本気の力…！\n異質で…故に、とても寂しい…\n本当の意味で彼女に届く声が、\nこの世界に存在するのでしょうか…", "", "ヴァイオレット", 4, 133103, 5, "vo_empress_133101_003", 1, 2, 355);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_133101_004", 133101, "あなたとの「繋がり」がある限り\n死が牙を剥くことはありません\n手を取り合い、共に参りましょう\nわたくしたちの未来のために！", "", "ヴァイオレット", 4, 133102, 5, "vo_empress_133101_004", 1, 3, 356);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_133601_001", 0, "フンっ、次から次へと…！　なら\n思う存分、大暴れしてやるから♪\nやっちゃうわよ、メドゥシアナ！\nアンタも！！", "", "メドゥーサ", 4, 133601, 5, "vo_empress_133601_001", 1, 1, 357);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_133601_002", 0, "どこの誰だか知らないけれど、\nアタシの魔眼でまとめて石に…って\nきゃああああ！　こんなバケモン級\nなら先に教えときなさいよ～っ！", "", "メドゥーサ", 4, 133601, 5, "vo_empress_133601_002", 1, 1, 358);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_133601_003", 0, "な…なんなの、アイツの『眼』…\nでもねっ、アタシはメドゥーサ\nゴルゴーンの、お姉ちゃんの妹よ！\n睨みあいで負けるわけがないわ！", "", "メドゥーサ", 4, 133603, 5, "vo_empress_133601_003", 1, 2, 359);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_133601_004", 133601, "知ってる？　蛇って執念深いのよ\nこの『眼』で見つけてやったわ\n幻境竜后、アンタが一番恐れること\nアタシとこいつが手をつなぐこと！", "", "メドゥーサ", 4, 133602, 5, "vo_empress_133601_004", 1, 3, 360);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_134701_001", 0, "この大地と大空を守るため、\n人の子らだけに任せてはおけません\n鳳凰のはばたきで、その野望ごと\n跡形もなく吹き飛ばしましょう！", "", "ホウオウ", 4, 134701, 5, "vo_empress_134701_001", 1, 1, 361);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_134701_002", 0, "さあ皆さん、ここが正念場です！\n私がいれば楽勝圧勝間違いなし！\n…えっ？　私が先頭？　えーと…\nあっちょっと待って押さないで！", "", "ホウオウ", 4, 134701, 5, "vo_empress_134701_002", 1, 1, 362);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_134701_003", 0, "羽が散って、ちっ、力が…\n幻境竜后、やるではないですか…\nしかし、私も不死鳥と呼ばれた身…\nただでやられは…ぴ、ぴよぉぉ～…", "", "ホウオウ", 4, 134703, 5, "vo_empress_134701_003", 1, 2, 363);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_134701_004", 134701, "幻境竜后、でしたか？\nあなたも運のない方ですね\n今の私は輪廻史上最強の鳳凰\nその鱗一つ残さず焼き尽くします！", "", "ホウオウ", 4, 134702, 5, "vo_empress_134701_004", 1, 3, 364);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_134901_001", 0, "ヲ～ッホッホ！　どいつもこいつも\n大層なおツラ構えしてますけどぉ？\nあたくし様の敵じゃありませんわ！\nほら馬ボーン！　お強化なさいな！", "", "カノン", 4, 134901, 5, "vo_empress_134901_001", 1, 1, 365);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_134901_002", 0, "いってぇ～ですわ！　あたくし様の\nお美しいお肌を傷つけましたわね！\nまとめてお成敗して差し上げますわ\nついてらっしゃいな！　馬ボーン！", "", "カノン", 4, 134901, 5, "vo_empress_134901_002", 1, 1, 366);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_134901_003", 0, "なんてタマですの…アースハイドラ\nよりデカいなんて聞いてませんわ！\nでも…ここでお尻尾巻いて逃げる\nなら、死んだ方がマシですわ…！", "", "カノン", 4, 134903, 5, "vo_empress_134901_003", 1, 2, 367);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_134901_004", 134901, "幻境竜后とやら、お覚悟なさいな\nあたくしと馬ボーンの前に立つなど\n100億万年お早いですわ！\n華麗にお成敗して差し上げますわ♪", "", "カノン", 4, 134902, 5, "vo_empress_134901_004", 1, 3, 368);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_135501_001", 0, "来たね、お姉さんの出番ってやつ♪\nキミと一緒に戦えるなんて、あたし\nテンション最高潮だよ！　あははっ\nさ、思いっきり暴れちゃおっか！", "", "アイラ", 4, 135501, 5, "vo_empress_135501_001", 1, 1, 369);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_135501_002", 0, "あれが…覇瞳皇帝のオリジナルだね\nま、関係ないや。本物でも偽物でも\n今度こそ決着つけてあげるから！\nお姉さんの拳…燃え盛ってるよー！", 10000, "アイラ", 4, 135501, 3, "vo_empress_135501_002", 1, 4005, 370);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_135501_003", 0, "幻境竜后…とんでもない相手だね\nあたしの拳だって届かないかも…\nそれでも、燃え尽きるまで戦うよ\nキミが信じてくれてる限り、ね！", "", "アイラ", 4, 135503, 5, "vo_empress_135501_003", 1, 2, 371);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_135501_004", 135501, "キミがいれば怖いものなし！\nお姉さん今、燃えに燃えてるよっ\n太陽より熱く燃える拳で…\n全部まとめてぶっ飛ばす！", "", "アイラ", 4, 135502, 5, "vo_empress_135501_004", 1, 3, 372);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_135601_001", 0, "どれほどの逆風の中にいても、\n諦めてはならない…そうだろう？\nかつて私が、他でもないキミたちに\nそう教えてもらったんだ…", "", "シナツ", 4, 135601, 5, "vo_empress_135601_001", 1, 1, 373);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_135601_002", 0, "私はこの世界の人々と出会い、\n失ったはずの希望を見つけられた\n今度は私が、皆に希望を届ける番だ\nこの刃、存分に振るわせてくれ", "", "シナツ", 4, 135601, 5, "vo_empress_135601_002", 1, 1, 374);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_135601_003", 0, "幻境竜后…私たちの世界を創造し、\nそして滅ぼそうとした張本人か…！\nその力がどんなに強大だとしても…\n私は…絶対に逃げたりなどしない！", "", "シナツ", 4, 135603, 5, "vo_empress_135601_003", 1, 2, 375);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_135601_004", 135601, "私の刃に、もはや一片の曇りもない\n皆と生きる未来を守り抜くために\n戦いつづける…ただそれだけだ\n─道を阻む者は全て斬り伏せる！", "", "シナツ", 4, 135602, 5, "vo_empress_135601_004", 1, 3, 376);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_135801_001", 0, "リ、リ、リーザちゃ…！\nリーザちゃはあてのこと、ヘタレの\nホジナシって思ってっかもだけど…\n前より成長したとこ、見せっから！", 10000, "ユキノ", 4, 135801, 3, "vo_empress_135801_001", 1, 4001, 377);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_135801_002", 0, "田舎者で世間知らずなあてだけど…\n騎士さと一緒にいろんなとこ行って\n大切な思い出、いっぱいできたよ…\nだから守りてぇんだ、この世界…！", "", "ユキノ", 4, 135801, 5, "vo_empress_135801_002", 1, 1, 378);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_135801_003", 0, "あ、あても、ちったぁでけぇけど…\n幻境竜后、で、でっかすぎ…！\nそ、それに竜まで…！　炎浴びたら\nあて、溶けちまうよぅ…！", "", "ユキノ", 4, 135803, 5, "vo_empress_135801_003", 1, 2, 379);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_135801_004", 135801, "「あてなんか」なんて、考えね…\n騎士さが信じてくれるなら、\nあてだって自分のこと、信じるよ\nあてと騎士さなら大丈夫、って…！", "", "ユキノ", 4, 135802, 5, "vo_empress_135801_004", 1, 3, 380);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_135901_001", 0, "リザ公…手前ェどの面下げて\n俺の前に出てきやがった\nまァいいさ、何聞いても今更だ\nここで落とし前つけてもらうぜ", 10000, "サツキ", 4, 135903, 3, "vo_empress_135901_001", 1, 4001, 381);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_135901_002", 0, "いつ死んでもいいなんて\nもう思っちゃいねぇさ\nこの悪玉どもより、図太くしぶとく\n生き抜いてやろうじゃねぇか", "", "サツキ", 4, 135901, 5, "vo_empress_135901_002", 1, 1, 382);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_135901_003", 0, "あれが幻境竜后か…\nハンパじゃねェや\nしゃあねぇ、こうなりゃ一丁\n死に花咲かすとするか", "", "サツキ", 4, 135901, 5, "vo_empress_135901_003", 1, 2, 383);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_135901_004", 135901, "世界だの未来だの現実だの…\n重いったらありゃしねぇぜ\n潰れるなよ、騎士公\n俺も一緒に担いでやっからさ", "", "サツキ", 4, 135902, 5, "vo_empress_135901_004", 1, 3, 384);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_136001_001", 0, "騎士さま、どうかご安心を…\nどれだけ厳しい運命が待って\nいたとしても…あなたのことは、\nわたしの糸が必ずお守りします", "", "アラクネ", 4, 136001, 5, "vo_empress_136001_001", 1, 1, 385);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_136001_002", 0, "…？　あの金髪の女性、なんだか\n見覚えあるような気が…いえ\n騎士さまの敵は、わたしの敵です\nそれだけです…", 10000, "アラクネ", 4, 136001, 3, "vo_empress_136001_002", 1, 4003, 386);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_136001_003", 0, "あれが幻境竜后さま…\nなんという恐るべき力\n…騎士さま、わたしの後ろに\n一度くらいは、庇えるはずです…", "", "アラクネ", 4, 136003, 5, "vo_empress_136001_003", 1, 2, 387);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_136001_004", 136001, "騎士さまという光が、わたしに力を\n与えてくれるのです。ともに未来を\n歩むためにも…この戦いに\n必ず勝ちましょう、騎士さま", "", "アラクネ", 4, 136002, 5, "vo_empress_136001_004", 1, 3, 388);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_136201_001", 0, "強そうな敵さんがいっぱい～っ！？\nこーなったら、ウルトラとっておき\nドーナツ！　ちょっと湿気てるけど\n…はい騎士ちゃん、あーんっ♪", "", "ナーナ", 4, 136201, 5, "vo_empress_136201_001", 1, 1, 389);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_136201_002", 0, "ナーナだって頑張れるんだよっ！\n騎士ちゃんに、そう教わったもん！\nだから、すごく怖いけど…でもっ…\nナーナ、逃げたりしないよぉっ！", "", "ナーナ", 4, 136201, 5, "vo_empress_136201_002", 1, 1, 390);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_136201_003", 0, "うぅ…あ、足が震えてきちゃった…\nでも動かなきゃ、戦わなきゃっ…\nわかってるのに、でもでもぉ…\nうえぇぇん、やっぱり怖いぃぃ！", "", "ナーナ", 4, 136201, 5, "vo_empress_136201_003", 1, 2, 391);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_136201_004", 136201, "今のナーナはよわよわウサギじゃ\nないんだよ。騎士ちゃんのためなら\nどんな敵さんだってやっつけちゃう\nつよつよウサギなんだから！", "", "ナーナ", 4, 136202, 5, "vo_empress_136201_004", 1, 3, 392);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_136901_001", 0, "リーザ姉しゃまが裏切ったなんて\nあたち、信じたくないでしゅ…！\nだから直接聞きにいきましゅ\n吸盤ぜんぶで捕まえてでも…！", 10000, "ルルィ", 4, 136903, 3, "vo_empress_136901_001", 1, 4001, 393);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_136901_002", 0, "姫姉しゃまも騎士しゃんも\nみなしゃん戦ってるんでしゅ\nあたちだって負けましぇん！\n一生懸命がんばりましゅ～！", "", "ルルィ", 4, 136901, 5, "vo_empress_136901_002", 1, 1, 394);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_136901_003", 0, "あ、あの方、こわいでしゅ…！\n丸呑みにされちゃいそうでしゅっ\nうじゅ…がんばりたいでしゅが…\n震えが止まらないでしゅ…！", "", "ルルィ", 4, 136903, 5, "vo_empress_136901_003", 1, 2, 395);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_136901_004", 136901, "あたちは強くないでしゅけど\n騎士しゃんとの約束がありましゅ\nだから誰にも負けましぇん！\nいっちょに、守りましゅよ！", "", "ルルィ", 4, 136902, 5, "vo_empress_136901_004", 1, 3, 396);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_139501_001", 0, "これから挑む敵がどれだけ強いと\nしても、勇往邁進していきます\nですからこの戦いでも、兄様の\nおそばで戦わせてくださいませ", "", "リリ", 4, 139501, 5, "vo_empress_139501_001", 1, 1, 397);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_139501_002", 0, "幻境竜后の手先、アルシャト…！\nリアさんやヴルム様を陥れた貴方を\n決して許す訳には参りません！\n不倶戴天─ここで成敗致します！", 10000, "リリ", 4, 139503, 3, "vo_empress_139501_002", 1, 4002, 398);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_139501_003", 0, "幻境竜后の力…これほどまでに\n強力無比だとは…で、ですが…\n何があろうとわたくしは兄様を\nお守りします…命に代えても、必ず", "", "リリ", 4, 139503, 5, "vo_empress_139501_003", 1, 2, 399);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_139501_004", 125801, "兄様への想いと、重ねてきた大切な\n時間が、たくさんの勇気と限界を\n超える奇跡をくれました。全ての人\nを救うため、参りましょう兄様…！", "", "リリ", 4, 139502, 5, "vo_empress_139501_004", 1, 3, 400);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_139601_001", 0, "お兄さん、もし怪我しちゃっても\nすぐに治癒しますからご安心を！\nわたし決めましたから…もう二度と\n自分自身から逃げないって…！", "", "クリア", 4, 139603, 5, "vo_empress_139601_001", 1, 1, 401);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "vo_empress_139601_002", 0, "…アルシャトさん…\n謝ったって許してあげませんよ？\nあなたの前では、わたしちょっと\nいい子じゃいられませんから…っ！", 10000, "クリア", 4, 139603, 3, "vo_empress_139601_002", 1, 4002, 402);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_139601_003", 0, "うぅっ…これが本気の幻境竜后…！\n…こんなの勝てっこありませんよ…\n…せめてお兄さんだけでも…なんて\n最後まで…諦めませんからっ…！", "", "クリア", 4, 139603, 5, "vo_empress_139601_003", 1, 2, 403);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_139601_004", 126001, "お兄さんの気持ちが胸に溢れて…\nあ、えへへ…なんだか視界が\n滲んできちゃいました…♪\nわたしはもう、負けませんよ…っ！", "", "クリア", 4, 139601, 5, "vo_empress_139601_004", 1, 3, 404);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_139701_001", 0, "てき、いっぱい、しかも、つよすぎ\nけど、まけないよ\nお兄のほっぺ、たべて\nふるぱわー", "", "プレシア", 4, 139701, 5, "vo_empress_139701_001", 1, 1, 405);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_139701_002", 0, "ん\nまだまだ、いける\nお兄、パパ、なかま、いる\nむしゃぶるい", "", "プレシア", 4, 139701, 5, "vo_empress_139701_002", 1, 1, 406);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_139701_003", 0, "しょうり、みえない\nせいぎ、まもれない\nそんなの、いや\nあきらめないよ、さいごまで", "", "プレシア", 4, 139703, 5, "vo_empress_139701_003", 1, 2, 407);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_139701_004", 126101, "て、つなぐ\nせいめいりょく、たかまる\nぜったいしょうり！", "", "プレシア", 4, 139702, 5, "vo_empress_139701_004", 1, 3, 408);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("", "vo_empress_140301_004", 140301, "七冠、幻境竜后──LoAの開発者\nあんたにコワいコト教えてあげるわ\n些細なバグと思って放置したら\nゲームを壊すこともあるってね…♪", "", "ティア", 4, 140301, 5, "vo_empress_140301_004", 1, 3, 409);
